using Lighthouse.Backend.Models;
using Lighthouse.Backend.Services.Interfaces;
using Lighthouse.Backend.Services.Interfaces.BackgroundServices;
using Lighthouse.Backend.Services.Interfaces.Repositories;

namespace Lighthouse.Backend.Services.Implementation.BackgroundServices
{
    /// <summary>
    /// Everything one pass needs about one owner: how far forward its observations reach, every
    /// chart it has, and how to find where its stored items begin.
    ///
    /// Every chart rather than the one that was opened, because two asks for the same owner are
    /// the same ask. Narrow this to one family and the other families' asks are dropped while the
    /// work they cover is still outstanding, and the charts they belong to never fill at all.
    ///
    /// Both family lists are the ones the live recording uses rather than a copy made here. A copy
    /// is a second place the set can be changed, and the two then disagree about what a scope
    /// records without anything saying so. Each family is only wrapped, so that a reading reaching
    /// back past the work the owner still keeps comes back empty.
    /// </summary>
    internal sealed record OverTimeFillTarget(
        DateOnly LastObservedOn,
        IReadOnlyList<PercentileFamilyReader> PercentileFamilies,
        IReadOnlyList<ProcessBehaviorFamilyReader> ProcessBehaviorFamilies,
        Action InvalidateReadCache,
        Func<DateOnly?> EarliestDayTheItemsSupport)
    {
        /// <summary>
        /// The owner the ask names, loaded from the pass's own scope, or null when it no longer exists.
        /// </summary>
        public static OverTimeFillTarget? For(IServiceProvider services, OverTimeFillRequest request)
        {
            return request.OwnerType switch
            {
                OwnerType.Team => ForTeam(services, request.OwnerId),
                OwnerType.Portfolio => ForPortfolio(services, request.OwnerId),
                _ => null,
            };
        }

        private static OverTimeFillTarget? ForTeam(IServiceProvider services, int teamId)
        {
            var team = services.GetRequiredService<IRepository<Team>>().GetById(teamId);
            if (team is null)
            {
                return null;
            }

            var metrics = services.GetRequiredService<ITeamMetricsService>();
            var workItems = services.GetRequiredService<IWorkItemRepository>();
            var clock = services.GetRequiredService<ILighthouseClock>();
            var lastObservedOn = clock.ToInstanceDay(team.UpdateTime);
            var retention = RetentionEdge.For(lastObservedOn, team);

            return new OverTimeFillTarget(
                lastObservedOn,
                [.. Implementation.PercentileFamilies.For(team, metrics).Select(retention.Guard)],
                [.. services.GetRequiredService<IProcessBehaviorSnapshotWriter>().FamiliesFor(team).Select(retention.Guard)],
                () => metrics.InvalidateTeamMetrics(team),
                () => retention.NoEarlierThanTheEdge(EarliestFinishedDay(
                    clock,
                    workItems.GetAllByPredicate(item => item.TeamId == teamId && item.ClosedDate != null)
                        .Select(item => item.ClosedDate))));
        }

        private static OverTimeFillTarget? ForPortfolio(IServiceProvider services, int portfolioId)
        {
            var portfolio = services.GetRequiredService<IRepository<Portfolio>>().GetById(portfolioId);
            if (portfolio is null)
            {
                return null;
            }

            var metrics = services.GetRequiredService<IPortfolioMetricsService>();
            var deliveries = services.GetRequiredService<IRepository<Feature>>();
            var clock = services.GetRequiredService<ILighthouseClock>();
            var lastObservedOn = clock.ToInstanceDay(portfolio.UpdateTime);
            var retention = RetentionEdge.For(lastObservedOn, portfolio);

            return new OverTimeFillTarget(
                lastObservedOn,
                [.. Implementation.PercentileFamilies.For(portfolio, metrics).Select(retention.Guard)],
                [.. services.GetRequiredService<IProcessBehaviorSnapshotWriter>().FamiliesFor(portfolio).Select(retention.Guard)],
                () => metrics.InvalidatePortfolioMetrics(portfolio),
                () => retention.NoEarlierThanTheEdge(EarliestFinishedDay(
                    clock,
                    deliveries
                        .GetAllByPredicate(delivery =>
                            delivery.ClosedDate != null && delivery.Portfolios.Any(owner => owner.Id == portfolioId))
                        .Select(delivery => delivery.ClosedDate))));
        }

        /// <summary>
        /// The first day the owner's stored items can support a reading, or null when nothing has ever
        /// finished. Asked of the database as one aggregate rather than by loading the items, because
        /// an owner with a long history has a lot of them and only the earliest one is wanted.
        /// </summary>
        private static DateOnly? EarliestFinishedDay(ILighthouseClock clock, IQueryable<DateTime?> finishedInstants)
        {
            var earliest = finishedInstants.Min();

            return earliest is null ? null : clock.ToInstanceDay(earliest.Value);
        }
    }
}

using System.Diagnostics;
using System.Threading.Channels;
using Lighthouse.Backend.Models;
using Lighthouse.Backend.Services.Implementation.DatabaseManagement;
using Lighthouse.Backend.Services.Interfaces;
using Lighthouse.Backend.Services.Interfaces.BackgroundServices;

namespace Lighthouse.Backend.Services.Implementation.BackgroundServices
{
    /// <summary>
    /// Works out the days a chart was missing, away from the request that noticed them. One queue, one
    /// reader, one scope per pass so each pass gets a database context of its own, and a drain that
    /// empties what is waiting at a moment the caller chooses.
    ///
    /// Deliberately not the shared update queue. That queue serves one owner at a time, shows every
    /// admitted item to the user as a cancellable task, and keeps the database maintenance gate shut
    /// for as long as anything is admitted. Filling in history is none of those things: it is
    /// invisible, interruptible, and every day it writes stays written, so it can stand down at any
    /// point and pick up on the next chart load.
    /// </summary>
    public sealed class OverTimeHistoryFiller : BackgroundService, IOverTimeHistoryFiller
    {
        /// <summary>
        /// How many owners may be waiting at once. Past that an ask is refused rather than queued, and
        /// its owner is at once free to be asked for again - the next chart load asks again, so nothing
        /// is lost by refusing one, whereas an unbounded queue on a read endpoint is a way to run the
        /// instance out of memory from the browser.
        /// </summary>
        private const int MostOwnersWaitingAtOnce = 256;

        // Operator alerting groups on the work rather than on the chart, and one pass covers every
        // chart an owner has, so every failure reported from a pass carries the same value here. A
        // per-chart value would split one alert into several.
        private const string MetricFamily = "OverTime";

        /// <summary>
        /// The most days one pass works out. A year-wide picker then fills over successive loads
        /// rather than in one unbounded walk, and every day written stays written, so the next load
        /// carries on from where this one stopped. Only days the pass actually works out count: one
        /// that falls outside what the owner's stored items support is stepped over for nothing, and
        /// counting it would let a period reaching back past the owner's history spend the whole pass
        /// on days that can never be written, leaving out the part the history does cover.
        /// </summary>
        private const int MostDaysOnePassWorksOut = 90;

        /// <summary>
        /// The longest one pass may keep going. This is not a throughput figure and does not move with
        /// the size of the instance: for as long as a pass is running, an operator who clicks Restore is
        /// refused, so this is how long someone may be left pressing a button that does nothing before
        /// the answer changes. Ten seconds is about as long as anyone waits at a control before deciding
        /// it is broken.
        ///
        /// A pass that reaches it hands the rest of its window back instead of finishing it, and loses
        /// nothing by that: every day already written stays written, and the next chart load asks for
        /// whatever is still missing. So an instance with a lot of history fills its charts in over more
        /// visits rather than holding the operator for longer - which is the direction this is meant to
        /// give way in.
        /// </summary>
        private static readonly TimeSpan LongestOnePassMayRun = TimeSpan.FromSeconds(10);

        // Wait rather than one of the drop modes, although nothing here ever waits: asks only ever go in
        // through TryWrite, which under Wait says no when the queue is full. Under the drop modes it says
        // yes and throws the ask away, so its owner would stay marked as already asked for and never be
        // filled again until the process restarts.
        private readonly Channel<OverTimeFillRequest> waiting = Channel.CreateBounded<OverTimeFillRequest>(
            new BoundedChannelOptions(MostOwnersWaitingAtOnce) { FullMode = BoundedChannelFullMode.Wait });

        private readonly HashSet<(int OwnerId, OwnerType OwnerType)> alreadyAsked = [];

        private readonly IServiceScopeFactory scopeFactory;
        private readonly ILogger<OverTimeHistoryFiller> logger;
        private readonly TimeSpan longestThisPassMayRun;

        private int passesRunning;

        public OverTimeHistoryFiller(IServiceScopeFactory scopeFactory, ILogger<OverTimeHistoryFiller> logger)
            : this(scopeFactory, logger, LongestOnePassMayRun)
        {
        }

        /// <summary>
        /// The same filler on a budget of the caller's choosing. Ten seconds of real waiting is not
        /// something a test can afford to spend, and a budget nothing in the suite can reach is one
        /// nobody can show is actually enforced.
        /// </summary>
        internal OverTimeHistoryFiller(
            IServiceScopeFactory scopeFactory, ILogger<OverTimeHistoryFiller> logger, TimeSpan longestThisPassMayRun)
        {
            this.scopeFactory = scopeFactory;
            this.logger = logger;
            this.longestThisPassMayRun = longestThisPassMayRun;
        }

        public bool HasPassInFlight => Volatile.Read(ref passesRunning) > 0;

        public void AskFor(OverTimeFillRequest request)
        {
            lock (alreadyAsked)
            {
                if (!alreadyAsked.Add(request.Key))
                {
                    return;
                }
            }

            if (waiting.Writer.TryWrite(request))
            {
                return;
            }

            Forget(request.Key);
        }

        public async Task DrainAsync(CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested && waiting.Reader.TryRead(out var request))
            {
                await RunOnePassAsync(request, cancellationToken);
            }
        }

        /// <summary>
        /// Works through the queue on the way out, for as long as the host's shutdown allowance lasts.
        /// A pass cut short by shutdown loses nothing permanently, but a day written is a day the next
        /// reader does not wait for.
        /// </summary>
        public override async Task StopAsync(CancellationToken cancellationToken)
        {
            await base.StopAsync(cancellationToken);
            await DrainAsync(cancellationToken);
        }

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            await foreach (var request in waiting.Reader.ReadAllAsync(stoppingToken))
            {
                await RunOnePassAsync(request, stoppingToken);
            }
        }

        private async Task RunOnePassAsync(OverTimeFillRequest request, CancellationToken cancellationToken)
        {
            try
            {
                using var scope = scopeFactory.CreateScope();

                await FillWhileCountedAsRunningAsync(scope.ServiceProvider, request, cancellationToken);
            }
            catch (Exception failure)
            {
                // Nothing escapes. An exception that ended the reader loop would stop history filling
                // itself in for as long as the process lives, with nobody told.
                logger.LogError(
                    failure,
                    "Over-time reconstruction pass failed for {OwnerType} {OwnerId} ({MetricFamily})",
                    request.OwnerType,
                    request.OwnerId,
                    MetricFamily);
            }
            finally
            {
                Forget(request.Key);
            }
        }

        private async Task FillWhileCountedAsRunningAsync(
            IServiceProvider services, OverTimeFillRequest request, CancellationToken cancellationToken)
        {
            Interlocked.Increment(ref passesRunning);

            try
            {
                await FillAsync(services, request, cancellationToken);
            }
            finally
            {
                Interlocked.Decrement(ref passesRunning);
            }
        }

        private async Task FillAsync(IServiceProvider services, OverTimeFillRequest request, CancellationToken cancellationToken)
        {
            // Asked before the owner is loaded, because loading it is already a query against a file a
            // restore may be about to replace. Asked after the pass counts as running rather than before,
            // so that either the gate sees this pass and refuses, or this pass sees the operation and
            // stops: checked the other way round, both could look at the same moment and both go ahead.
            var maintenance = services.GetRequiredService<DatabaseMaintenanceGate>();
            if (MaintenanceNeedsTheDatabase(maintenance))
            {
                ReportStandingDownForMaintenance(request);
                return;
            }

            var target = OverTimeFillTarget.For(services, request);
            if (target is null)
            {
                return;
            }

            var writers = new OverTimeWriters(
                services.GetRequiredService<IPercentileSnapshotWriter>(),
                services.GetRequiredService<IProcessBehaviorSnapshotWriter>());
            var memo = services.GetRequiredService<ReconstructionMemo>();
            var progress = new PassProgress();

            try
            {
                await WalkAsync(writers, maintenance, memo, request, target, progress, cancellationToken);
            }
            finally
            {
                // Working a day out warms the shared metrics cache under the same (owner, window) keys
                // the widgets read. Leaving those entries behind would serve the UI values computed for
                // a day that is not the one it is asking about. Once per pass and for the whole owner:
                // the metrics services evict by owner and nothing finer, so the live entries go with
                // the historical ones, and the dashboard pays one recompute for a pass nobody asked it
                // for. That is the accepted price of not adding a per-key eviction for this - and a pass
                // that worked out no day read nothing, so it does not pay it.
                if (progress.DaysTried > 0)
                {
                    target.InvalidateReadCache();
                }

                ReportHowManyDaysCouldNotBeWritten(request, progress);
            }
        }

        private async Task WalkAsync(
            OverTimeWriters writers,
            DatabaseMaintenanceGate maintenance,
            ReconstructionMemo memo,
            OverTimeFillRequest request,
            OverTimeFillTarget target,
            PassProgress progress,
            CancellationToken cancellationToken)
        {
            // Where the owner's history begins is a property of its stored items, so working it out
            // means a query over them. That is why it happens here rather than where the missing days
            // were noticed: a chart load may cost a scan of the rows it already holds and no more.
            var earliestDayTheItemsSupport = target.EarliestDayTheItemsSupport();
            memo.TheWalkReachesBackNoFurtherThan(
                request.OwnerId, request.OwnerType, earliestDayTheItemsSupport);

            var timeSpentOnThisPass = Stopwatch.StartNew();

            foreach (var day in request.CandidateDays)
            {
                // A backup, restore or clear replaces the database file, so writing into it while one
                // runs - or while an operator this pass turned away is waiting to start one - is what
                // this stands down for. Asked once per day as well as once per pass because a pass
                // outlives the moment it started: the operator may press the button halfway through the
                // walk. Giving up mid-walk costs nothing here - the days already written stay written,
                // and the next chart load asks for whatever is still missing.
                if (MaintenanceNeedsTheDatabase(maintenance))
                {
                    ReportStandingDownForMaintenance(request);

                    break;
                }

                // The other thing that stops a pass short, and it stops it for the operator's sake
                // rather than the database's: a restore is refused for as long as a pass is running, so
                // how long a pass may run is how long someone can be left at a button that does nothing.
                // The rest of the window is given back rather than hurried, and asked for again on the
                // next chart load.
                //
                // Never before the pass has tried a day. A budget short enough to stop a pass at nothing
                // would be a pass that never finishes a window however many times the chart is opened,
                // which is not a slower fill but no fill at all.
                if (progress.DaysTried > 0 && timeSpentOnThisPass.Elapsed >= longestThisPassMayRun)
                {
                    logger.LogInformation(
                        "Over-time reconstruction gave the rest of the window back for {OwnerType} {OwnerId} ({MetricFamily}) after {DaysDone} days; the next chart load asks for what is left",
                        request.OwnerType,
                        request.OwnerId,
                        MetricFamily,
                        progress.DaysTried);

                    break;
                }

                if (progress.DaysTried >= MostDaysOnePassWorksOut)
                {
                    break;
                }

                if (cancellationToken.IsCancellationRequested ||
                    IsOutsideWhatTheStoredItemsSupport(day, earliestDayTheItemsSupport, target.LastObservedOn))
                {
                    continue;
                }

                progress.TriedADay();
                await FillOneDayAsync(writers, memo, request, day, target, progress);
            }
        }

        /// <summary>
        /// Two narrow questions rather than whether the gate is blocked at all: a pass in flight is
        /// one of the things that blocks it, so asking that would have every pass stand down for itself.
        /// </summary>
        private static bool MaintenanceNeedsTheDatabase(DatabaseMaintenanceGate maintenance)
            => maintenance.IsMaintenanceOperationActive || maintenance.IsMaintenanceOperationWaiting;

        private void ReportStandingDownForMaintenance(OverTimeFillRequest request)
        {
            logger.LogInformation(
                "Over-time reconstruction stood down for {OwnerType} {OwnerId} ({MetricFamily}); a database maintenance operation is running or waiting to start",
                request.OwnerType,
                request.OwnerId,
                MetricFamily);
        }

        /// <summary>
        /// Nothing was stored before the owner's first finished item, and past its last observation
        /// its items are frozen at the break. A reading at either end would draw a confident line over
        /// a period the stored data says nothing about - and because items age out past the owner's
        /// cutoff, a walk of a fixed width regardless of the data reaches further into that with every
        /// day that passes.
        /// </summary>
        private static bool IsOutsideWhatTheStoredItemsSupport(
            DateOnly day, DateOnly? earliestDayTheItemsSupport, DateOnly lastObservedOn)
            => earliestDayTheItemsSupport is null || day < earliestDayTheItemsSupport || day > lastObservedOn;

        /// <summary>
        /// One day of every chart the owner has, written on its own. A day that cannot be written is
        /// one day: the pass carries on to the next, and the day it skipped is simply still missing
        /// when the next chart load looks. Abandoning the walk here would cost the other eighty-nine
        /// days over a single bad one.
        ///
        /// The two kinds of chart are staged and committed separately so that a fault in one leaves
        /// the other's rows written rather than discarding them - but the day is only settled once
        /// both got through, because a day remembered as settled is never offered to a pass again.
        /// </summary>
        private async Task FillOneDayAsync(
            OverTimeWriters writers,
            ReconstructionMemo memo,
            OverTimeFillRequest request,
            DateOnly day,
            OverTimeFillTarget target,
            PassProgress progress)
        {
            var percentilesFailure = await TryWriteDayAsync(
                () =>
                {
                    foreach (var family in target.PercentileFamilies)
                    {
                        writers.Percentiles.FillDayIfAbsent(request.OwnerId, request.OwnerType, family.MetricType, day, family.ReadPercentiles);
                    }
                },
                writers.Percentiles.SaveFilledDay);

            var limitsFailure = await TryWriteDayAsync(
                () =>
                {
                    foreach (var family in target.ProcessBehaviorFamilies)
                    {
                        writers.ProcessBehavior.FillDayIfAbsent(request.OwnerId, request.OwnerType, family, day);
                    }
                },
                writers.ProcessBehavior.SaveFilledDay);

            var failure = percentilesFailure ?? limitsFailure;
            if (failure is not null)
            {
                // Deliberately not remembered: a day lost to a fault is worth another try, unlike one
                // the walk declined on the merits.
                ReportADayThatCouldNotBeWritten(request, day, failure, progress);
                return;
            }

            // Worked out once is worked out for good: the reading follows from the owner's stored
            // items, and those change only when the owner is refreshed - which is the event that
            // forgets this again. The day the walk declined to write is the case this exists for,
            // because left unremembered it is found missing by every later chart load, each of
            // which starts another pass that declines it again.
            memo.TheWalkHasAlreadyWorkedOut(request.OwnerId, request.OwnerType, day);
        }

        /// <summary>The fault that stopped this half of the day being written, or null once it is.</summary>
        private static async Task<Exception?> TryWriteDayAsync(Action stageEveryFamily, Func<Task> commit)
        {
            try
            {
                stageEveryFamily();
                await commit();

                return null;
            }
            catch (Exception failure)
            {
                return failure;
            }
        }

        /// <summary>
        /// A fault that breaks one day usually breaks every day of the pass, and everything at Warning
        /// or worse lands in the Task Manager's Recent Problems - so a line per day would put up to
        /// ninety of them there on every chart load. Only the first carries its cause; the rest are
        /// counted and told once, when the pass ends.
        /// </summary>
        private void ReportADayThatCouldNotBeWritten(
            OverTimeFillRequest request, DateOnly day, Exception failure, PassProgress progress)
        {
            progress.ADayCouldNotBeWritten();
            if (progress.DaysThatCouldNotBeWritten > 1)
            {
                return;
            }

            logger.LogError(
                failure,
                "Over-time reconstruction could not write {Day} for {OwnerType} {OwnerId} ({MetricFamily}); the rest of the pass continues, and any further day it cannot write is counted rather than logged",
                day,
                request.OwnerType,
                request.OwnerId,
                MetricFamily);
        }

        /// <summary>
        /// A Warning rather than a second Error: the first failure is already at Error with its cause,
        /// and it is the one to act on. This line only says how far the same fault reached, and still
        /// lands in Recent Problems beside it. A pass where only one day failed has nothing to add.
        /// </summary>
        private void ReportHowManyDaysCouldNotBeWritten(OverTimeFillRequest request, PassProgress progress)
        {
            if (progress.DaysThatCouldNotBeWritten < 2)
            {
                return;
            }

            logger.LogWarning(
                "Over-time reconstruction could not write {DaysThatFailed} days for {OwnerType} {OwnerId} ({MetricFamily}) in one pass; the first was logged with its cause, and the next chart load asks for them again",
                progress.DaysThatCouldNotBeWritten,
                request.OwnerType,
                request.OwnerId,
                MetricFamily);
        }

        private void Forget((int OwnerId, OwnerType OwnerType) key)
        {
            lock (alreadyAsked)
            {
                alreadyAsked.Remove(key);
            }
        }

        /// <summary>
        /// The two write policies a pass commits through. Held together because a day is one day
        /// across both of them: the pass writes each family's row and only then counts the day done.
        /// </summary>
        private sealed record OverTimeWriters(
            IPercentileSnapshotWriter Percentiles,
            IProcessBehaviorSnapshotWriter ProcessBehavior);

        /// <summary>
        /// What one pass has got through and how many of those days it could not write, held outside
        /// the walk so that however the walk ends - a check that stops it, the end of the window, or an
        /// exception - the pass still knows what it did. A day counts as tried from the moment the pass
        /// starts working it out, because that is when it starts reading.
        /// </summary>
        private sealed class PassProgress
        {
            public int DaysTried { get; private set; }

            public int DaysThatCouldNotBeWritten { get; private set; }

            public void TriedADay() => DaysTried++;

            public void ADayCouldNotBeWritten() => DaysThatCouldNotBeWritten++;
        }
    }
}

using Lighthouse.Backend.Models;
using Lighthouse.Backend.Models.Events;
using Lighthouse.Backend.Services.Interfaces.DomainEvents;

namespace Lighthouse.Backend.Services.Implementation.BackgroundServices
{
    /// <summary>
    /// What earlier passes already found out about an owner, so that a chart load stops asking for
    /// days no pass will ever be able to write. There are two such days: one that falls before the
    /// owner's first finished item, and one a pass worked out and left with no row because nothing
    /// finished in the window behind it. Neither can be produced by trying again, and with nowhere to
    /// write that down both are found missing on every single chart load - so looking at a settled
    /// period keeps costing a pass, forever.
    ///
    /// A day's reading is worked out from the owner's stored items, and those change only when the
    /// owner is refreshed. That is why everything here can be thrown away the moment it is, and why
    /// none of it is worth keeping across a restart: losing the lot costs one wasted pass and nothing
    /// else. Nothing may be asserted from what this holds - a scenario that only passes because the
    /// memo is warm is a scenario whose real predicate is wrong.
    /// </summary>
    public sealed class ReconstructionMemo :
        IDomainEventHandler<TeamDataRefreshed>,
        IDomainEventHandler<PortfolioFeaturesRefreshed>
    {
        /// <summary>
        /// How much is kept. Past either bound what is held is dropped rather than grown, because an
        /// unbounded cache on a path a browser can drive is a way to run the instance out of memory,
        /// and dropping it costs one pass that would otherwise have been skipped.
        /// </summary>
        private const int MostOwnersRemembered = 256;

        private const int MostDaysRememberedPerOwner = 512;

        private readonly Dictionary<(int OwnerId, OwnerType OwnerType), OwnerNotes> byOwner = [];

        /// <summary>
        /// Whether a pass has already established that this day cannot be written. Answered from a
        /// dictionary and nothing else: the caller is a read somebody is waiting on.
        /// </summary>
        public bool NoPassCanWrite(int ownerId, OwnerType ownerType, DateOnly day)
        {
            lock (byOwner)
            {
                return byOwner.TryGetValue((ownerId, ownerType), out var notes) && notes.RulesOut(day);
            }
        }

        /// <summary>
        /// Where the owner's stored items begin. A null day means nothing has ever finished, which
        /// rules out every day rather than none.
        /// </summary>
        public void TheWalkReachesBackNoFurtherThan(
            int ownerId, OwnerType ownerType, DateOnly? earliestDayTheItemsSupport)
        {
            lock (byOwner)
            {
                NotesFor((ownerId, ownerType)).ReachesBackNoFurtherThan(earliestDayTheItemsSupport);
            }
        }

        /// <summary>
        /// A day nothing more can be got out of. Only a day every one of the owner's charts has been
        /// through counts: written down after some of them, the rest are never asked for again and the
        /// families that never got their turn become permanently unfillable.
        /// </summary>
        public void TheWalkHasAlreadyWorkedOut(int ownerId, OwnerType ownerType, DateOnly day)
        {
            lock (byOwner)
            {
                NotesFor((ownerId, ownerType)).AlreadyWorkedOut(day);
            }
        }

        public Task HandleAsync(TeamDataRefreshed domainEvent, CancellationToken cancellationToken)
        {
            Forget(domainEvent.TeamId, OwnerType.Team);
            return Task.CompletedTask;
        }

        public Task HandleAsync(PortfolioFeaturesRefreshed domainEvent, CancellationToken cancellationToken)
        {
            Forget(domainEvent.PortfolioId, OwnerType.Portfolio);
            return Task.CompletedTask;
        }

        private void Forget(int ownerId, OwnerType ownerType)
        {
            lock (byOwner)
            {
                byOwner.Remove((ownerId, ownerType));
            }
        }

        private OwnerNotes NotesFor((int OwnerId, OwnerType OwnerType) key)
        {
            if (byOwner.TryGetValue(key, out var notes))
            {
                return notes;
            }

            if (byOwner.Count >= MostOwnersRemembered)
            {
                byOwner.Clear();
            }

            var fresh = new OwnerNotes();
            byOwner.Add(key, fresh);

            return fresh;
        }

        /// <summary>
        /// One owner's two findings. The floor is held as a day rather than as a day and a flag: not
        /// yet resolved is the smallest day there is, so nothing falls below it, and nothing finished
        /// at all is the largest, so everything does.
        /// </summary>
        private sealed class OwnerNotes
        {
            private readonly HashSet<DateOnly> alreadyWorkedOut = [];

            private DateOnly earliestDayTheItemsSupport = DateOnly.MinValue;

            public bool RulesOut(DateOnly day) => day < earliestDayTheItemsSupport || alreadyWorkedOut.Contains(day);

            public void ReachesBackNoFurtherThan(DateOnly? earliestFinishedDay)
                => earliestDayTheItemsSupport = earliestFinishedDay ?? DateOnly.MaxValue;

            public void AlreadyWorkedOut(DateOnly day)
            {
                if (alreadyWorkedOut.Count >= MostDaysRememberedPerOwner)
                {
                    alreadyWorkedOut.Clear();
                }

                alreadyWorkedOut.Add(day);
            }
        }
    }
}

using Lighthouse.Backend.Models;
using Lighthouse.Backend.Models.Metrics;
using Lighthouse.Backend.Services.Interfaces;

namespace Lighthouse.Backend.Services.Implementation.BackgroundServices
{
    /// <summary>
    /// The oldest day an owner still keeps finished work from. Every refresh deletes what finished
    /// before it, so a day worked out afterwards may only read a stretch that lies wholly on or after
    /// this edge: a stretch reaching past it is averaged over work that is partly gone, reads lower
    /// than the owner ever was, and is written once and never corrected.
    ///
    /// Judged from the owner's last refresh rather than from the day being worked out, because that
    /// refresh is what deleted the work. A day turned away here stays turned away until the next
    /// refresh, which only moves the edge forward - so the refusal is as settled as any other day the
    /// walk declines, and is remembered the same way.
    ///
    /// Applied to each reading rather than to the day, because how far back a reading looks belongs to
    /// the reading: a thirty-day cycle time window can lie inside what is kept on a day where the
    /// ninety-day one does not. The window the reading is asked for is the one the writers chose, so
    /// this never works out a window of its own.
    /// </summary>
    internal sealed class RetentionEdge
    {
        private const string TheStretchReachesPastTheEdge =
            "The stretch these limits are drawn from reaches back further than finished work is kept.";

        private readonly DateOnly? oldestDayStillKept;

        private readonly DateTime? pinnedStretchStartsOn;

        private RetentionEdge(DateOnly? oldestDayStillKept, DateTime? pinnedStretchStartsOn)
        {
            this.oldestDayStillKept = oldestDayStillKept;
            this.pinnedStretchStartsOn = pinnedStretchStartsOn;
        }

        /// <summary>
        /// A cutoff of zero or less keeps finished work for ever, and then there is no edge. The owner's
        /// pinned stretch is taken along because limits are drawn from it rather than from the day's own
        /// window whenever one is pinned.
        /// </summary>
        public static RetentionEdge For(DateOnly lastObservedOn, WorkTrackingSystemOptionsOwner owner)
            => new(
                owner.DoneItemsCutoffDays > 0 ? lastObservedOn.AddDays(-owner.DoneItemsCutoffDays) : null,
                owner.ProcessBehaviourChartBaselineStartDate);

        /// <summary>
        /// The first day the walk may work out: no day older than the edge has any reading left to
        /// give, whatever its window, so the walk steps over those days rather than spending its
        /// allowance on them.
        /// </summary>
        public DateOnly? NoEarlierThanTheEdge(DateOnly? earliestFinishedDay)
        {
            if (earliestFinishedDay is null || oldestDayStillKept is null)
            {
                return earliestFinishedDay;
            }

            return earliestFinishedDay > oldestDayStillKept ? earliestFinishedDay : oldestDayStillKept;
        }

        /// <summary>A reading whose window reaches past the edge comes back empty, which the writer leaves unwritten.</summary>
        public PercentileFamilyReader Guard(PercentileFamilyReader family)
            => family with
            {
                ReadPercentiles = (windowStart, windowEnd) =>
                    ReachesPastTheEdge(windowStart) ? [] : family.ReadPercentiles(windowStart, windowEnd),
            };

        /// <summary>
        /// Limits whose stretch reaches past the edge come back unusable, which the writer leaves unwritten.
        ///
        /// A pinned stretch is the one the limits come from, so it is the one judged, and the day's own
        /// window says nothing about them. Judging the day being worked out would not catch it: the pinned
        /// stretch does not move with the day, so it lies within the retention of an old enough day long
        /// after the owner's last refresh has deleted it.
        /// </summary>
        public ProcessBehaviorFamilyReader Guard(ProcessBehaviorFamilyReader family)
            => family with
            {
                ReadChart = (windowStart, windowEnd, asOf) =>
                    ReachesPastTheEdge(pinnedStretchStartsOn ?? windowStart)
                        ? ProcessBehaviourChart.NotReady(BaselineStatus.BaselineInvalid, TheStretchReachesPastTheEdge)
                        : family.ReadChart(windowStart, windowEnd, asOf),
            };

        /// <summary>
        /// Both a window start and a pinned stretch start arrive as a calendar day encoded at UTC midnight,
        /// so taking the date is taking the day, not reducing an instant.
        /// </summary>
        private bool ReachesPastTheEdge(DateTime stretchStartsOn)
            => oldestDayStillKept is { } edge && DateOnly.FromDateTime(stretchStartsOn) < edge;
    }
}

namespace Lighthouse.Backend.Services.Implementation
{
    public record BaselineValidationResult(bool IsValid, string ErrorMessage = "");

    public static class BaselineValidationService
    {
        private const int MinimumBaselineDays = 14;

        // The browser cannot know the instance's day, so a picked end one day past it is accepted.
        // That covers a viewer whose zone is up to a day ahead of the instance's; anything further
        // is refused as future.
        private const int DaysAViewerCanBeAheadOfTheInstance = 1;

        // The baseline bounds are user-picked calendar days stored at UTC midnight, so
        // DateOnly.FromDateTime is correct here and ToInstanceDay would be wrong - it would move a
        // date picked west of UTC back a day.
        public static BaselineValidationResult Validate(DateTime? startDate, DateTime? endDate, int doneItemsCutoffDays, DateOnly today)
        {
            if (startDate == null && endDate == null)
            {
                return new BaselineValidationResult(true);
            }

            if (startDate == null || endDate == null)
            {
                return new BaselineValidationResult(false, "Baseline start and end dates must both be set or both be empty.");
            }

            var lengthResult = ValidateLength(startDate.Value, endDate.Value);
            if (!lengthResult.IsValid)
            {
                return lengthResult;
            }

            if (DateOnly.FromDateTime(endDate.Value) > today.AddDays(DaysAViewerCanBeAheadOfTheInstance))
            {
                return new BaselineValidationResult(false, "Baseline end date must not be in the future.");
            }

            return ValidateCutoff(startDate.Value, doneItemsCutoffDays, today);
        }

        // With no baseline configured, the display window stands in for one. It ends on whatever day
        // the viewer asked for, which may be ahead of the instance's day, so it is never refused as
        // future.
        public static BaselineValidationResult ValidateDisplayWindowAsBaseline(DateTime startDate, DateTime endDate, int doneItemsCutoffDays, DateOnly today)
        {
            var lengthResult = ValidateLength(startDate, endDate);
            if (!lengthResult.IsValid)
            {
                return lengthResult;
            }

            return ValidateCutoff(startDate, doneItemsCutoffDays, today);
        }

        private static BaselineValidationResult ValidateLength(DateTime startDate, DateTime endDate)
        {
            if (endDate.Date <= startDate.Date)
            {
                return new BaselineValidationResult(false, "Baseline end date must be after the start date.");
            }

            var baselineDays = (endDate.Date - startDate.Date).Days;
            if (baselineDays < MinimumBaselineDays)
            {
                return new BaselineValidationResult(false, $"Baseline must be at least {MinimumBaselineDays} days. Current: {baselineDays} days.");
            }

            return new BaselineValidationResult(true);
        }

        private static BaselineValidationResult ValidateCutoff(DateTime startDate, int doneItemsCutoffDays, DateOnly today)
        {
            if (doneItemsCutoffDays <= 0)
            {
                // CutOff = 0 means full history - no need to check
                return new BaselineValidationResult(true);
            }

            var cutoffDate = today.AddDays(-doneItemsCutoffDays);
            if (DateOnly.FromDateTime(startDate) < cutoffDate)
            {
                return new BaselineValidationResult(false, $"Baseline start date falls outside the data cutoff window ({doneItemsCutoffDays} days). Data may be incomplete.");
            }

            return new BaselineValidationResult(true);
        }
    }
}

using Lighthouse.Backend.Cache;
using Lighthouse.Backend.Models;
using Lighthouse.Backend.Models.Forecast;
using Lighthouse.Backend.Models.Metrics;
using Lighthouse.Backend.Services.Interfaces;
using Lighthouse.Backend.Services.Interfaces.Forecast;

namespace Lighthouse.Backend.Services.Implementation
{
    public abstract class BaseMetricsService(int refreshRateInMinutes, IServiceProvider serviceProvider, ILighthouseClock clock)
    {
        /// <summary>
        /// Derived services forward the clock here rather than capturing it themselves (CS9107).
        /// </summary>
        protected ILighthouseClock Clock { get; } = clock;

        private Cache<string, object> MetricsCache => field ??= serviceProvider.GetRequiredService<Cache<string, object>>();

        private IForecastService ForecastService => field ??= serviceProvider.GetRequiredService<IForecastService>();

        protected record InfoMetric(int Value);

        protected static Dictionary<int, IReadOnlyList<WorkItemStateTransition>> GroupTransitionsByItem(
            IEnumerable<(int ItemId, WorkItemStateTransition Transition)> transitions)
        {
            return transitions
                .GroupBy(entry => entry.ItemId)
                .ToDictionary(
                    group => group.Key,
                    group => (IReadOnlyList<WorkItemStateTransition>)group
                        .Select(entry => entry.Transition)
                        .OrderBy(transition => transition.TransitionedAt)
                        .ToList());
        }

        /// <summary>
        /// The state an item was in on <paramref name="asOf"/>, or null when the history says nothing
        /// about that day and the caller should keep the item's current state.
        /// </summary>
        /// <remarks>
        /// Day granularity, deliberately: a transition part-way through the end date belongs to that
        /// day, matching how GenerateWorkInProgressByDay picks the population the caller is projecting.
        ///
        /// Teams and portfolios share this rule but apply it differently — a WorkItem can be copied
        /// wholesale, whereas a Feature cannot (its copy constructor drops Forecasts / FeatureWork /
        /// Portfolios that FeatureDto needs, and the entities are EF-tracked so mutating them would
        /// write the projection back to the database). Hence one rule, two applications.
        /// </remarks>
        protected static WorkItemStateTransition? ResolveStateAsOf(
            IReadOnlyList<WorkItemStateTransition> transitions, DateTime asOf)
        {
            return transitions
                .Where(transition => transition.TransitionedAt.Date <= asOf.Date)
                .OrderBy(transition => transition.TransitionedAt)
                .LastOrDefault();
        }

        protected static IEnumerable<AgeInStatePercentilesDto> ComputeAgeInStatePercentiles(
            IEnumerable<WorkItem> completedItemsInWindow,
            IReadOnlyList<string> doingStatesInOrder,
            IReadOnlyList<int> requestedPercentiles,
            IReadOnlyList<PercentileValue> cycleTimePercentiles)
        {
            var items = completedItemsInWindow.Where(item => item.StartedDate.HasValue).ToList();
            if (items.Count == 0 || doingStatesInOrder.Count == 0)
            {
                return [];
            }

            var lastStateIndex = doingStatesInOrder.Count - 1;
            var columns = new List<AgeInStatePercentilesDto>();

            for (var index = 0; index < doingStatesInOrder.Count; index++)
            {
                var state = doingStatesInOrder[index];

                if (index == lastStateIndex)
                {
                    columns.Add(new AgeInStatePercentilesDto(state, CloneCycleTimeColumn(cycleTimePercentiles)));
                    continue;
                }

                var observations = items
                    .Select(item => LastExitCumulativeAge(item, state))
                    .Where(age => age.HasValue)
                    .Select(age => age!.Value)
                    .ToList();

                if (observations.Count > 0)
                {
                    columns.Add(BuildAgeInStatePercentilesDto(state, observations, requestedPercentiles));
                }
            }

            return ClampPercentilesNonDecreasing(columns);
        }

        private static List<PercentileValue> CloneCycleTimeColumn(IReadOnlyList<PercentileValue> cycleTimePercentiles)
        {
            return cycleTimePercentiles
                .Select(percentile => new PercentileValue(percentile.Percentile, percentile.Value))
                .ToList();
        }

        private static int? LastExitCumulativeAge(WorkItem item, string state)
        {
            if (!item.StartedDate.HasValue)
            {
                return null;
            }

            var lastExit = item.SyncedTransitions
                .Where(transition => transition.FromState == state)
                .Select(transition => (DateTime?)transition.TransitionedAt)
                .DefaultIfEmpty(null)
                .Max();

            return lastExit.HasValue
                ? CumulativeAgeAtExit(item.StartedDate.Value, lastExit.Value)
                : null;
        }

        protected static IReadOnlyList<AgeInStatePercentilesDto> ClampPercentilesNonDecreasing(
            IReadOnlyList<AgeInStatePercentilesDto> orderedPercentilesByState)
        {
            var runningMaxByRank = new Dictionary<int, int>();
            var clamped = new List<AgeInStatePercentilesDto>(orderedPercentilesByState.Count);

            foreach (var statePercentiles in orderedPercentilesByState)
            {
                var clampedPercentiles = statePercentiles.Percentiles
                    .Select(percentile => ClampRank(percentile, runningMaxByRank))
                    .ToList();

                clamped.Add(new AgeInStatePercentilesDto(statePercentiles.State, clampedPercentiles));
            }

            return clamped;
        }

        private static PercentileValue ClampRank(PercentileValue percentile, Dictionary<int, int> runningMaxByRank)
        {
            var runningMax = runningMaxByRank.TryGetValue(percentile.Percentile, out var max) ? max : int.MinValue;
            var clampedValue = Math.Max(percentile.Value, runningMax);
            runningMaxByRank[percentile.Percentile] = clampedValue;

            return new PercentileValue(percentile.Percentile, clampedValue);
        }

        private static AgeInStatePercentilesDto BuildAgeInStatePercentilesDto(string state, List<int> observations, IReadOnlyList<int> requestedPercentiles)
        {
            var percentiles = requestedPercentiles
                .Select(percentile => new PercentileValue(percentile, PercentileCalculator.CalculatePercentile(observations, percentile)))
                .ToList();

            return new AgeInStatePercentilesDto(state, percentiles);
        }

        private static int CumulativeAgeAtExit(DateTime startedDate, DateTime exitedAt)
        {
            return (int)(exitedAt.Date - startedDate.Date).TotalDays + 1;
        }

        protected static IReadOnlyList<CumulativeStateTimeStateRowDto> ComputeCumulativeStateTime(
            IEnumerable<WorkItem> includedItems,
            IReadOnlyList<string> workflowStateOrder,
            DateTime nowSnapshot)
        {
            var items = includedItems.ToList();
            if (items.Count == 0)
            {
                return [];
            }

            var completedVisitsByState = GroupCompletedVisitDurationsByState(items);
            var ongoingByState = GroupOngoingContributionsByState(items, nowSnapshot);

            return workflowStateOrder
                .Select((state, order) => BuildCumulativeStateTimeRow(
                    state,
                    order,
                    completedVisitsByState.TryGetValue(state, out var completed) ? completed : [],
                    ongoingByState.TryGetValue(state, out var ongoing) ? ongoing : []))
                .ToList();
        }

        protected static FlowEfficiencyInfoDto ComputeFlowEfficiency(
            IReadOnlyList<CumulativeStateTimeStateRowDto> doingStateRows,
            IReadOnlyList<string> waitDisplayStates,
            bool isConfigured)
        {
            var totalDoingDays = doingStateRows.Sum(row => row.TotalDays);
            if (!isConfigured || totalDoingDays <= 0)
            {
                return new FlowEfficiencyInfoDto(isConfigured, HasDataInScope: totalDoingDays > 0, EfficiencyPercent: 0, totalDoingDays, WaitDays: 0);
            }

            var waitStateSet = waitDisplayStates.ToHashSet(StringComparer.OrdinalIgnoreCase);
            var waitDays = doingStateRows
                .Where(row => waitStateSet.Contains(row.State))
                .Sum(row => row.TotalDays);

            var efficiencyPercent = (totalDoingDays - waitDays) / totalDoingDays * 100.0;

            return new FlowEfficiencyInfoDto(isConfigured, HasDataInScope: true, efficiencyPercent, totalDoingDays, waitDays);
        }

        private static Dictionary<string, List<double>> GroupOngoingContributionsByState(IEnumerable<WorkItem> items, DateTime nowSnapshot)
        {
            var byState = new Dictionary<string, List<double>>();

            foreach (var item in items.Where(IsInFlight))
            {
                if (!byState.TryGetValue(item.State, out var durations))
                {
                    durations = [];
                    byState[item.State] = durations;
                }

                durations.Add(OngoingDuration(item, nowSnapshot));
            }

            return byState;
        }

        protected static IReadOnlyList<CumulativeStateTimeItemDto> ComputeCumulativeStateTimeItems(
            IEnumerable<WorkItem> includedItems,
            string state,
            DateTime nowSnapshot)
        {
            return includedItems
                .Select(item => (item, days: ContributionForState(item, state, nowSnapshot)))
                .Where(entry => entry.days > 0)
                .Select(entry => new CumulativeStateTimeItemDto
                {
                    WorkItemId = entry.item.Id,
                    ReferenceId = entry.item.ReferenceId,
                    Title = entry.item.Name,
                    Type = entry.item.Type,
                    State = entry.item.State,
                    StateCategory = entry.item.StateCategory.ToString(),
                    Url = entry.item.Url,
                    DaysContributed = entry.days,
                })
                .ToList();
        }

        protected static IReadOnlyList<CumulativeStateTimeCandidateRowDto> ProjectCumulativeStateTimeCandidates(IEnumerable<WorkItem> includedItems)
        {
            return includedItems
                .Select(item => new CumulativeStateTimeCandidateRowDto(item.Id, item.ReferenceId, item.Name, item.Type))
                .ToList();
        }

        protected static List<WorkItem> NarrowToSelectedItems(List<WorkItem> includedItems, IReadOnlyList<int>? itemIds)
        {
            if (itemIds is not { Count: > 0 })
            {
                return includedItems;
            }

            var selection = itemIds.ToHashSet();
            return includedItems.Where(item => selection.Contains(item.Id)).ToList();
        }

        protected static string SelectionCacheSuffix(IReadOnlyList<int>? itemIds)
        {
            if (itemIds is not { Count: > 0 })
            {
                return string.Empty;
            }

            return $"_Selection_{string.Join("-", itemIds.OrderBy(id => id))}";
        }

        private static Dictionary<string, List<(int ItemId, double Days)>> GroupCompletedVisitDurationsByState(IEnumerable<WorkItem> items)
        {
            var byState = new Dictionary<string, List<(int ItemId, double Days)>>();

            foreach (var visit in items.SelectMany(CompletedVisits))
            {
                if (!byState.TryGetValue(visit.State, out var visits))
                {
                    visits = [];
                    byState[visit.State] = visits;
                }

                visits.Add((visit.ItemId, visit.Days));
            }

            return byState;
        }

        private static IEnumerable<(string State, int ItemId, double Days)> CompletedVisits(WorkItem item)
        {
            return RawCompletedVisits(item)
                .Select(visit => (visit.State, visit.ItemId, (visit.End - visit.Start).TotalDays));
        }

        private static DateTime? WorkflowEntryIntoFirstState(WorkItem item, List<WorkItemStateTransition> orderedTransitions)
        {
            var startedDate = item.StartedDate;

            // StartedDate is the entry into the first Doing state. If the first recorded state was
            // exited at or before then, it is a pre-Doing (To Do) state the item has occupied since it
            // was created — its entry is CreatedDate. Otherwise the first recorded state IS the first
            // Doing state, entered at StartedDate. This keeps the default Doing-only view anchored at
            // StartedDate while letting a named window that spans To Do states measure from creation.
            var firstStateLeftBeforeDoingStart = startedDate.HasValue
                && orderedTransitions.Count > 0
                && orderedTransitions[0].TransitionedAt <= startedDate.Value;

            return firstStateLeftBeforeDoingStart
                ? (item.CreatedDate ?? startedDate)
                : (startedDate ?? item.CreatedDate);
        }

        private static IEnumerable<(string State, int ItemId, DateTime Start, DateTime End)> RawCompletedVisits(WorkItem item)
        {
            var orderedTransitions = item.SyncedTransitions
                .OrderBy(transition => transition.TransitionedAt)
                .ToList();

            var entryIntoState = WorkflowEntryIntoFirstState(item, orderedTransitions);

            foreach (var transition in orderedTransitions)
            {
                if (entryIntoState.HasValue && !string.IsNullOrEmpty(transition.FromState))
                {
                    yield return (transition.FromState, item.Id, entryIntoState.Value, transition.TransitionedAt);
                }

                entryIntoState = transition.TransitionedAt;
            }
        }

        protected static IReadOnlyList<string> ScopedCumulativeStateOrder(IReadOnlyList<string> statesInOrder, string startState, string endState)
        {
            var startThreshold = PositionOf(statesInOrder, startState);
            var endThreshold = PositionOf(statesInOrder, endState);
            if (startThreshold < 0 || endThreshold <= startThreshold)
            {
                return [];
            }

            return statesInOrder.Skip(startThreshold).Take(endThreshold - startThreshold).ToList();
        }

        protected static IEnumerable<PercentileValue> BuildPercentiles(List<int> values) =>
        [
            new PercentileValue(50, PercentileCalculator.CalculatePercentile(values, 50)),
            new PercentileValue(70, PercentileCalculator.CalculatePercentile(values, 70)),
            new PercentileValue(85, PercentileCalculator.CalculatePercentile(values, 85)),
            new PercentileValue(95, PercentileCalculator.CalculatePercentile(values, 95)),
        ];

        protected static List<(int Id, string StartState, string EndState)> ResolveValidNamedDefinitions(
            WorkTrackingSystemOptionsOwner owner,
            IReadOnlyList<string> statesInOrder)
        {
            return owner.CycleTimeDefinitions
                .Where(owner.IsCycleTimeDefinitionValid)
                .Select(definition => (
                    definition.Id,
                    StartState: ResolveBoundaryState(owner, statesInOrder, definition.StartState),
                    EndState: ResolveBoundaryState(owner, statesInOrder, definition.EndState)))
                .ToList();
        }

        protected static List<NamedCycleTimeValue> NamedValuesForItem(
            WorkItem item,
            IReadOnlyList<string> statesInOrder,
            IReadOnlyList<(int Id, string StartState, string EndState)> definitions)
        {
            return definitions
                .Select(definition => (definition.Id, days: NamedCycleTimeDays(item, statesInOrder, definition.StartState, definition.EndState)))
                .Where(entry => entry.days.HasValue)
                .Select(entry => new NamedCycleTimeValue(entry.Id, entry.days!.Value))
                .ToList();
        }

        protected static List<string> DisplayStatesInOrder(WorkTrackingSystemOptionsOwner owner)
            => owner.CategoryLists().DisplayStatesInWorkflowOrder();

        protected static string ResolveBoundaryState(WorkTrackingSystemOptionsOwner owner, IReadOnlyList<string> statesInOrder, string boundaryState)
            => owner.CategoryLists().WorkflowEntryFor(statesInOrder, boundaryState) ?? boundaryState;

        protected static int? NamedCycleTimeDays(WorkItem item, IReadOnlyList<string> statesInOrder, string startState, string endState)
        {
            var window = NamedCycleTimeWindow(item, statesInOrder, startState, endState);
            if (window == null)
            {
                return null;
            }

            return (int)(window.Value.End.Date - window.Value.Start.Date).TotalDays + 1;
        }

        protected static (DateTime Start, DateTime End)? NamedCycleTimeWindow(WorkItem item, IReadOnlyList<string> statesInOrder, string startState, string endState)
        {
            var startThreshold = PositionOf(statesInOrder, startState);
            var endThreshold = PositionOf(statesInOrder, endState);
            if (startThreshold < 0 || endThreshold <= startThreshold)
            {
                return null;
            }

            var stateEntries = OrderedStateEntries(item, statesInOrder).ToList();

            var startMoment = stateEntries
                .Where(entry => entry.Rank >= startThreshold)
                .Select(entry => (DateTime?)entry.EnteredAt)
                .FirstOrDefault();
            if (!startMoment.HasValue)
            {
                return null;
            }

            // The clock stops at the LAST forward crossing into the end boundary (an item that reaches
            // the end, is reopened below it, and reaches it again ends on the final re-close — aligning
            // with the default Cycle Time's ClosedDate and keeping a wider window from measuring shorter
            // than a narrower one). A re-stamp that never dropped below the boundary is NOT a new crossing,
            // so time spent sitting in the end state does not count towards the cycle time.
            DateTime? endMoment = null;
            var previousRank = int.MinValue;
            foreach (var entry in stateEntries)
            {
                var isForwardCrossing = previousRank < endThreshold && entry.Rank >= endThreshold;
                if (isForwardCrossing && entry.EnteredAt >= startMoment.Value)
                {
                    endMoment = entry.EnteredAt;
                }

                previousRank = entry.Rank;
            }

            if (!endMoment.HasValue)
            {
                return null;
            }

            return (startMoment.Value, endMoment.Value);
        }

        private static IEnumerable<(int Rank, DateTime EnteredAt)> OrderedStateEntries(WorkItem item, IReadOnlyList<string> statesInOrder)
        {
            var orderedTransitions = item.SyncedTransitions
                .OrderBy(transition => transition.TransitionedAt)
                .ToList();

            var workflowEntry = WorkflowEntryIntoFirstState(item, orderedTransitions);
            if (!workflowEntry.HasValue)
            {
                yield break;
            }

            var firstState = orderedTransitions.Count > 0 ? orderedTransitions[0].FromState : item.State;
            yield return (PositionOf(statesInOrder, firstState), workflowEntry.Value);

            foreach (var transition in orderedTransitions)
            {
                yield return (PositionOf(statesInOrder, transition.ToState), transition.TransitionedAt);
            }
        }

        private static int PositionOf(IReadOnlyList<string> statesInOrder, string state)
        {
            for (var index = 0; index < statesInOrder.Count; index++)
            {
                if (StateCategoryLists.IsSameState(statesInOrder[index], state))
                {
                    return index;
                }
            }

            return -1;
        }

        private static bool IsInFlight(WorkItem item)
        {
            return item.StateCategory == StateCategories.Doing && item.CurrentStateEnteredAt.HasValue;
        }

        private static double OngoingDuration(WorkItem item, DateTime nowSnapshot)
        {
            // An item that entered its current state after the window end has accrued no ongoing time
            // within the window — never a negative bar segment.
            return Math.Max(0, (nowSnapshot - item.CurrentStateEnteredAt!.Value).TotalDays);
        }

        private static double ContributionForState(WorkItem item, string state, DateTime nowSnapshot)
        {
            var completed = CompletedVisits(item)
                .Where(visit => visit.State == state)
                .Sum(visit => visit.Days);

            var ongoing = IsInFlight(item) && item.State == state
                ? OngoingDuration(item, nowSnapshot)
                : 0;

            return completed + ongoing;
        }

        private static CumulativeStateTimeStateRowDto BuildCumulativeStateTimeRow(
            string state,
            int workflowOrder,
            IReadOnlyList<(int ItemId, double Days)> completedVisits,
            List<double> ongoingDurations)
        {
            var completedContribution = completedVisits.Sum(visit => visit.Days);
            var ongoingContribution = ongoingDurations.Sum();
            var completedItemCount = completedVisits.Select(visit => visit.ItemId).Distinct().Count();

            return new CumulativeStateTimeStateRowDto(
                State: state,
                WorkflowOrder: workflowOrder,
                TotalDays: completedContribution + ongoingContribution,
                CompletedContributionDays: completedContribution,
                OngoingContributionDays: ongoingContribution,
                ItemCount: completedItemCount + ongoingDurations.Count,
                CompletedItemCount: completedItemCount,
                OngoingItemCount: ongoingDurations.Count,
                MeanDays: CumulativeMean(completedVisits),
                MedianDays: CumulativeMedian(completedVisits));
        }

        private static double CumulativeMean(IReadOnlyList<(int ItemId, double Days)> completedVisits)
        {
            return completedVisits.Count == 0 ? 0 : completedVisits.Average(visit => visit.Days);
        }

        private static double? CumulativeMedian(IReadOnlyList<(int ItemId, double Days)> completedVisits)
        {
            if (completedVisits.Count == 0)
            {
                return null;
            }

            var roundedDays = completedVisits.Select(visit => (int)Math.Round(visit.Days)).ToList();
            return PercentileCalculator.CalculatePercentile(roundedDays, 50);
        }

