        private static Dictionary<int, List<WorkItemBase>> GenerateRunChartByDay(DateTime startDate, DateTime endDate, IEnumerable<WorkItemBase> items, Func<DateTime, WorkItemBase, int> getDayIndex)
        {
            var totalDays = (endDate - startDate).Days + 1;

            var runChartData = InitializeRunChartDictionary(totalDays);

            foreach (var item in items)
            {
                var dayIndex = getDayIndex(startDate, item);
                if (dayIndex >= 0 && dayIndex < totalDays)
                {
                    runChartData[dayIndex].Add(item);
                }
            }

            return runChartData;
        }

        protected (int[] Values, int[][] WorkItemIdsPerDay) GenerateTotalWorkItemAgeByDay(DateTime startDate, DateTime endDate, IEnumerable<WorkItemBase> items)
        {
            var totalDays = (endDate - startDate).Days + 1;
            var values = new int[totalDays];
            var workItemIdsPerDay = new int[totalDays][];

            for (var index = 0; index < totalDays; index++)
            {
                var currentDate = startDate.AddDays(index);
                var itemsInProgressOnDay = items.Where(i => WasItemProgressOnDay(currentDate, i)).ToList();

                var currentDay = DateOnly.FromDateTime(currentDate);
                var totalAge = itemsInProgressOnDay.Sum(item => AgeInDaysOn(currentDay, item.StartedDate ?? item.CreatedDate));

                values[index] = totalAge;
                workItemIdsPerDay[index] = itemsInProgressOnDay.Select(i => i.Id).ToArray();
            }

            return (values, workItemIdsPerDay);
        }

        protected Dictionary<int, List<WorkItemBase>> GenerateWorkInProgressByDay(DateTime startDate, DateTime endDate, IEnumerable<WorkItemBase> items)
        {
            var totalDays = (endDate - startDate).Days + 1;
            var runChartData = InitializeRunChartDictionary(totalDays);

            for (var index = 0; index < totalDays; index++)
            {
                var currentDate = startDate.AddDays(index);
                var itemsInProgressOnDay = items.Where(i => WasItemProgressOnDay(currentDate, i));

                runChartData[index].AddRange(itemsInProgressOnDay);
            }

            return runChartData;
        }

        protected IEnumerable<TItem> ClosedInDateRange<TItem>(IEnumerable<TItem> items, DateTime startDate, DateTime endDate) where TItem : WorkItemBase
        {
            var firstDay = DateOnly.FromDateTime(startDate);
            var lastDay = DateOnly.FromDateTime(endDate);

            return items.Where(item => WasClosedBetween(item, firstDay, lastDay));
        }

        protected IEnumerable<TItem> InSizeChartWindow<TItem>(IEnumerable<TItem> items, DateTime startDate, DateTime endDate) where TItem : WorkItemBase
        {
            var firstDay = DateOnly.FromDateTime(startDate);
            var lastDay = DateOnly.FromDateTime(endDate);

            return items.Where(item =>
                (item.StateCategory == StateCategories.Done && WasClosedBetween(item, firstDay, lastDay)) ||
                item.StateCategory == StateCategories.ToDo ||
                item.StateCategory == StateCategories.Doing);
        }

        // The stored close instant is reduced to a day once, in the instance's time zone, and compared
        // against day bounds the caller already reduced, so a late-evening close lands on its local day.
        private bool WasClosedBetween(WorkItemBase item, DateOnly firstDay, DateOnly lastDay)
        {
            if (!item.ClosedDate.HasValue)
            {
                return false;
            }

            var closedDay = Clock.ToInstanceDay(item.ClosedDate.Value);

            return closedDay >= firstDay && closedDay <= lastDay;
        }

        private int GetClosedIndexForItem(DateTime startDate, WorkItemBase item)
        {
            return GetDateIndexBasedOnStartDate(startDate, item.ClosedDate);
        }

        private int GetCreatedIndexForItem(DateTime startDate, WorkItemBase item)
        {
            return GetDateIndexBasedOnStartDate(startDate, item.CreatedDate);
        }

        private int GetStartedIndexForItem(DateTime startDate, WorkItemBase item)
        {
            return GetDateIndexBasedOnStartDate(startDate, item.StartedDate);
        }

        private int GetDateIndexBasedOnStartDate(DateTime startDate, DateTime? date)
        {
            if (!date.HasValue)
            {
                return -1;
            }

            return Clock.ToInstanceDay(date.Value).DayNumber - DateOnly.FromDateTime(startDate).DayNumber;
        }

        private int AgeInDaysOn(DateOnly day, DateTime? startedAt)
        {
            if (!startedAt.HasValue)
            {
                return 1;
            }

            return day.DayNumber - Clock.ToInstanceDay(startedAt.Value).DayNumber + 1;
        }

        private bool WasItemProgressOnDay(DateTime day, WorkItemBase item)
        {
            var startedDate = item.StartedDate ?? item.CreatedDate;

            // Item not started --> Can't be in progress
            if (!startedDate.HasValue)
            {
                return false;
            }

            if (!item.ClosedDate.HasValue && item.StateCategory == StateCategories.Done)
            {
                return false;
            }

            var instanceDay = DateOnly.FromDateTime(day);
            var wasStartedOnOrAfterDay = Clock.ToInstanceDay(startedDate.Value) <= instanceDay;
            var wasClosedOnOrAfterDay = !item.ClosedDate.HasValue || Clock.ToInstanceDay(item.ClosedDate.Value) > instanceDay;

            return wasStartedOnOrAfterDay && wasClosedOnOrAfterDay;
        }

        protected TMetric GetFromCacheIfExists<TMetric, TEntity>(TEntity entity, string metricIdentifier, Func<TMetric> calculateMetric, ILogger logger) where TMetric : class where TEntity : class, IEntity
        {
            var cacheKey = MetricsCacheKey.For(entity, metricIdentifier);

            var cachedMetric = GetMetricFromCache<TMetric>(cacheKey);

            if (cachedMetric != null)
            {
                logger.LogDebug("Found {CacheKey} in Cache - Don't calculate", cacheKey);
                return cachedMetric;
            }

            logger.LogDebug("Did not find {CacheKey} in Cache - Recalculating", cacheKey);
            var metric = calculateMetric();

            StoreMetricInCache(cacheKey, metric);

            return metric;
        }

        protected void InvalidateMetrics<TEntity>(TEntity entity, ILogger logger) where TEntity : class, IEntity
        {
            logger.LogDebug("Invalidating Metrics for Entity Id: {EntityId}", entity.Id);
            var ownerPrefix = MetricsCacheKey.PrefixFor(entity);
            var entityKeys = MetricsCache.Keys.Where(k => k.StartsWith(ownerPrefix)).ToList();
            foreach (var entry in entityKeys)
            {
                MetricsCache.Remove(entry);
            }
        }

        protected static ThroughputInfoDto BuildThroughputInfoDto(
            int currentTotal,
            int previousTotal,
            int periodDays,
            DateTime currentStart,
