                "Total Throughput",
                currentLabel,
                currentTotal.ToString(),
                previousLabel,
                previousTotal.ToString(),
                percentageDelta,
                null);

            return new ThroughputInfoDto(currentTotal, dailyAverage, comparison);
        }

