using Lighthouse.Backend.Services.Interfaces.WorkItems;
using Microsoft.Extensions.Logging;

namespace Lighthouse.Backend.Services.Implementation.DomainEvents
{
    public class BlockedCountSnapshotRecordingHandler
        : IDomainEventHandler<TeamDataRefreshed>,
          IDomainEventHandler<PortfolioFeaturesRefreshed>
    {
        private readonly ITeamMetricsService teamMetricsService;
        private readonly IPortfolioMetricsService portfolioMetricsService;
        private readonly IRepository<Team> teamRepository;
        private readonly IRepository<Portfolio> portfolioRepository;
        private readonly IBlockedItemService blockedItemService;
        private readonly IBlockedCountSnapshotRepository snapshotRepository;
        private readonly ILighthouseClock clock;
        private readonly ILogger<BlockedCountSnapshotRecordingHandler> logger;

#pragma warning disable S107 // Bug #5567 adds the clock as the named seam for "which calendar day is it?"; folding it into an aggregate with the unrelated metrics services and repositories would hide it.
        public BlockedCountSnapshotRecordingHandler(
            ITeamMetricsService teamMetricsService,
            IPortfolioMetricsService portfolioMetricsService,
            IRepository<Team> teamRepository,
            IRepository<Portfolio> portfolioRepository,
            IBlockedItemService blockedItemService,
            IBlockedCountSnapshotRepository snapshotRepository,
            ILighthouseClock clock,
            ILogger<BlockedCountSnapshotRecordingHandler> logger)
#pragma warning restore S107
        {
            this.teamMetricsService = teamMetricsService;
            this.portfolioMetricsService = portfolioMetricsService;
            this.teamRepository = teamRepository;
            this.portfolioRepository = portfolioRepository;
            this.blockedItemService = blockedItemService;
            this.snapshotRepository = snapshotRepository;
            this.clock = clock;
            this.logger = logger;
        }

        public async Task HandleAsync(TeamDataRefreshed domainEvent, CancellationToken cancellationToken)
        {
            // Stryker disable once all: diagnostic log text is not behaviour
            logger.LogDebug("Recording blocked-item snapshot for Team {TeamId}", domainEvent.TeamId);

            var team = teamRepository.GetById(domainEvent.TeamId);
            if (team == null)
            {
                return;
            }

            var blockedEligibleItems = teamMetricsService.GetBlockedEligibleItemsForTeam(team);

            var blockedCount = blockedEligibleItems.Count(item => blockedItemService.IsBlocked(item, team));

            await UpsertSnapshotAsync(domainEvent.TeamId, OwnerType.Team, blockedCount);
        }

        public async Task HandleAsync(PortfolioFeaturesRefreshed domainEvent, CancellationToken cancellationToken)
        {
            // Stryker disable once all: diagnostic log text is not behaviour
            logger.LogDebug("Recording blocked-item snapshot for Portfolio {PortfolioId}", domainEvent.PortfolioId);

            var portfolio = portfolioRepository.GetById(domainEvent.PortfolioId);
            if (portfolio == null)
            {
                return;
            }

            var blockedEligibleFeatures = portfolioMetricsService.GetBlockedEligibleFeaturesForPortfolio(portfolio);

            var blockedCount = blockedEligibleFeatures.Count(item => blockedItemService.IsBlocked(item, portfolio));

            await UpsertSnapshotAsync(domainEvent.PortfolioId, OwnerType.Portfolio, blockedCount);
        }

        private async Task UpsertSnapshotAsync(int ownerId, OwnerType ownerType, int blockedCount)
        {
            var today = clock.Today;
            var existing = snapshotRepository.GetByPredicate(
                s => s.OwnerId == ownerId && s.OwnerType == ownerType && s.RecordedAt == today);

            if (existing != null)
            {
                existing.BlockedCount = blockedCount;
            }
            else
            {
                var snapshot = new BlockedCountSnapshot
                {
                    OwnerId = ownerId,
                    OwnerType = ownerType,
                    RecordedAt = today,
                    BlockedCount = blockedCount,
                };
                snapshotRepository.Add(snapshot);
            }

            await snapshotRepository.Save();
        }
    }
}

using Lighthouse.Backend.Models;
using Lighthouse.Backend.Models.Events;
using Lighthouse.Backend.Services.Implementation.WorkTrackingConnectors.Csv;
using Lighthouse.Backend.Services.Interfaces;
using Lighthouse.Backend.Services.Interfaces.DomainEvents;
using Lighthouse.Backend.Services.Interfaces.Repositories;
using Lighthouse.Backend.Services.Interfaces.WorkItems;
using Microsoft.Extensions.Logging;

namespace Lighthouse.Backend.Services.Implementation.DomainEvents
{
    /// <summary>
    /// Demo-only: after a demo owner refreshes, synthesizes a backdated blocked history so the
    /// Blocked Over Time chart shows a real trend and each bar drills into the items blocked at that
    /// date. The per-sync <see cref="BlockedCountSnapshotRecordingHandler"/> only ever records
    /// "today" and <see cref="WorkItemBlockedTransitionCaptureHandler"/> stamps EnteredAt = now, so a
    /// freshly-loaded demo has no history to visualise. This handler backfills that once.
    ///
    /// Gated to demo connections (SynthesizeStateJourneyForDemo = true) and idempotent (skips once a
    /// backdated snapshot exists), so it never touches a real customer's blocked data.
    /// </summary>
    public class DemoBlockedHistoryBackfillHandler
        : IDomainEventHandler<TeamDataRefreshed>,
          IDomainEventHandler<PortfolioFeaturesRefreshed>
    {
        private const int HistoryWindowDays = 14;

        private readonly ITeamMetricsService teamMetricsService;
        private readonly IPortfolioMetricsService portfolioMetricsService;
        private readonly IRepository<Team> teamRepository;
        private readonly IRepository<Portfolio> portfolioRepository;
        private readonly IRepository<WorkTrackingSystemConnection> connectionRepository;
        private readonly IBlockedItemService blockedItemService;
        private readonly IWorkItemBlockedTransitionRepository transitionRepository;
        private readonly IFeatureBlockedTransitionRepository featureTransitionRepository;
        private readonly IBlockedCountSnapshotRepository snapshotRepository;
        private readonly ILighthouseClock clock;
        private readonly ILogger<DemoBlockedHistoryBackfillHandler> logger;

#pragma warning disable S107 // This demo backfill genuinely needs both metrics services, both owner repos, the connection repo (demo gate), the blocked-item service and all three keyspace repos (team transitions, feature transitions and snapshots); grouping them into an aggregate purely to dodge the 7-param threshold would add indirection without a domain rationale (same rationale as BlockedCountSnapshotRecordingHandler + TeamMetricsController).
        public DemoBlockedHistoryBackfillHandler(
            ITeamMetricsService teamMetricsService,
            IPortfolioMetricsService portfolioMetricsService,
            IRepository<Team> teamRepository,
            IRepository<Portfolio> portfolioRepository,
            IRepository<WorkTrackingSystemConnection> connectionRepository,
            IBlockedItemService blockedItemService,
            IWorkItemBlockedTransitionRepository transitionRepository,
            IFeatureBlockedTransitionRepository featureTransitionRepository,
            IBlockedCountSnapshotRepository snapshotRepository,
            ILighthouseClock clock,
            ILogger<DemoBlockedHistoryBackfillHandler> logger)
#pragma warning restore S107
        {
            this.teamMetricsService = teamMetricsService;
            this.portfolioMetricsService = portfolioMetricsService;
            this.teamRepository = teamRepository;
            this.portfolioRepository = portfolioRepository;
            this.connectionRepository = connectionRepository;
            this.blockedItemService = blockedItemService;
            this.transitionRepository = transitionRepository;
            this.featureTransitionRepository = featureTransitionRepository;
            this.snapshotRepository = snapshotRepository;
            this.clock = clock;
            this.logger = logger;
        }

        public async Task HandleAsync(TeamDataRefreshed domainEvent, CancellationToken cancellationToken)
        {
            var team = teamRepository.GetById(domainEvent.TeamId);
            if (team == null || !IsDemoOwner(team))
            {
                return;
            }

            var blockedItems = teamMetricsService.GetBlockedEligibleItemsForTeam(team)
                .Where(item => blockedItemService.IsBlocked(item, team))
                .OrderBy(item => item.Id)
                .Select(item => (item.Id, item.StartedDate))
                .ToList();

            await BackfillAsync(team.Id, OwnerType.Team, blockedItems);
        }

        public async Task HandleAsync(PortfolioFeaturesRefreshed domainEvent, CancellationToken cancellationToken)
        {
            var portfolio = portfolioRepository.GetById(domainEvent.PortfolioId);
            if (portfolio == null || !IsDemoOwner(portfolio))
            {
                return;
            }

            var blockedFeatures = portfolioMetricsService.GetBlockedEligibleFeaturesForPortfolio(portfolio)
                .Where(feature => blockedItemService.IsBlocked(feature, portfolio))
                .OrderBy(feature => feature.Id)
                .Select(feature => (feature.Id, feature.StartedDate))
                .ToList();

            await BackfillAsync(portfolio.Id, OwnerType.Portfolio, blockedFeatures);
        }

        private bool IsDemoOwner(WorkTrackingSystemOptionsOwner owner)
        {
            var connection = connectionRepository.GetById(owner.WorkTrackingSystemConnectionId);

            return connection != null
                && connection.Options.Any(option =>
                    option.Key == CsvWorkTrackingOptionNames.SynthesizeStateJourneyForDemo
                    && bool.TryParse(option.Value, out var synthesize) && synthesize);
        }

        private async Task BackfillAsync(int ownerId, OwnerType ownerType, List<(int WorkItemId, DateTime? StartedDate)> blockedItems)
        {
            if (blockedItems.Count == 0)
            {
                return;
            }

            var todayDate = clock.Today;
            var today = clock.TodayAsUtcMidnight;

            var entered = SpreadEnteredDates(blockedItems, today);

            // Blocked spells for the portfolio path live in the dedicated FeatureBlockedTransition
            // keyspace (ADR-102/103, US-05). Its idempotency keys off feature-spell presence, NOT the
            // snapshot guard below: after slice 01 a demo portfolio already has backdated snapshots but
            // no feature spells, so a snapshot-gated write would short-circuit and synthesize nothing on
            // exactly the instances this backfill targets. UpsertBackdatedFeatureSpell is idempotent per
            // (portfolio, feature), so a second refresh adds no spell.
            if (ownerType == OwnerType.Portfolio)
            {
                foreach (var (featureId, enteredAt) in entered)
                {
                    UpsertBackdatedFeatureSpell(ownerId, featureId, enteredAt);
                }

                await featureTransitionRepository.Save();
            }

            // Idempotency: a backdated snapshot means this demo owner's snapshot history was already
            // backfilled. GetAllByPredicate (not GetByPredicate/Exists, which both use SingleOrDefault)
            // because the guard predicate matches the whole history window, not a single row.
            var alreadyBackfilled = snapshotRepository
                .GetAllByPredicate(snapshot =>
                    snapshot.OwnerId == ownerId
                    && snapshot.OwnerType == ownerType
                    && snapshot.RecordedAt < todayDate)
                .Any();

            if (alreadyBackfilled)
            {
                return;
            }

            // Stryker disable once all: diagnostic log text is not behaviour
            logger.LogInformation(
                "Backfilling demo blocked history for {OwnerType} {OwnerId} ({Count} blocked items)",
                ownerType, ownerId, blockedItems.Count);

            // Team blocked spells live in the team keyspace only. The portfolio path's item ids are
            // Feature.Ids, which collide with real WorkItem ids and would corrupt the team historic
            // blocked read (a WorkItemBlockedTransition keyed by a Feature.Id makes a never-blocked work
            // item read blocked). So only the team path writes WorkItemBlockedTransition rows; the
            // portfolio path's feature spells were written above into FeatureBlockedTransition.
            if (ownerType == OwnerType.Team)
            {
                foreach (var (workItemId, enteredAt) in entered)
                {
                    UpsertBackdatedTransition(workItemId, enteredAt);
                }

                await transitionRepository.Save();
            }

            var earliest = entered.Min(e => e.EnteredAt).Date;
            for (var day = earliest; day <= today; day = day.AddDays(1))
            {
                var blockedCount = entered.Count(e => e.EnteredAt.Date <= day);
                UpsertSnapshot(ownerId, ownerType, DateOnly.FromDateTime(day), blockedCount);
            }

            await snapshotRepository.Save();
        }

        private static List<(int WorkItemId, DateTime EnteredAt)> SpreadEnteredDates(
            List<(int WorkItemId, DateTime? StartedDate)> blockedItems, DateTime today)
        {
            var count = blockedItems.Count;

            return blockedItems
                .Select((item, index) =>
                {
                    // Spread blocked-since across the window so the count climbs over time instead of
                    // stepping from 0 to N on a single day. Earliest item blocked longest.
                    var daysAgo = HistoryWindowDays - (int)Math.Round((double)index / count * HistoryWindowDays);
                    var enteredAt = today.AddDays(-daysAgo);

                    // Never claim an item was blocked before it was even started.
                    var startedCap = item.StartedDate?.Date;
                    if (startedCap.HasValue && enteredAt < startedCap.Value)
                    {
                        enteredAt = startedCap.Value;
                    }

                    return (item.WorkItemId, EnteredAt: enteredAt);
                })
                .ToList();
        }

        private void UpsertBackdatedTransition(int workItemId, DateTime enteredAt)
        {
            var existingOpen = transitionRepository.GetByPredicate(
                transition => transition.WorkItemId == workItemId && transition.LeftAt == null);

            if (existingOpen != null)
            {
                existingOpen.EnteredAt = enteredAt;
                return;
            }

            transitionRepository.Add(new WorkItemBlockedTransition
            {
                WorkItemId = workItemId,
                EnteredAt = enteredAt,
                LeftAt = null,
            });
        }

        private void UpsertBackdatedFeatureSpell(int portfolioId, int featureId, DateTime enteredAt)
        {
            var existingOpen = featureTransitionRepository.GetOpenSpell(portfolioId, featureId);

            if (existingOpen != null)
            {
                existingOpen.EnteredAt = enteredAt;
                return;
            }

            featureTransitionRepository.Add(new FeatureBlockedTransition
            {
                FeatureId = featureId,
                PortfolioId = portfolioId,
                EnteredAt = enteredAt,
                LeftAt = null,
            });
        }

        private void UpsertSnapshot(int ownerId, OwnerType ownerType, DateOnly recordedAt, int blockedCount)
        {
            var existing = snapshotRepository.GetByPredicate(snapshot =>
                snapshot.OwnerId == ownerId
                && snapshot.OwnerType == ownerType
                && snapshot.RecordedAt == recordedAt);

            if (existing != null)
            {
                existing.BlockedCount = blockedCount;
                return;
            }

            snapshotRepository.Add(new BlockedCountSnapshot
            {
                OwnerId = ownerId,
                OwnerType = ownerType,
                RecordedAt = recordedAt,
                BlockedCount = blockedCount,
            });
        }
    }
}

using Lighthouse.Backend.Models;
using Lighthouse.Backend.Models.Events;
using Lighthouse.Backend.Services.Implementation.WorkTrackingConnectors.Csv;
using Lighthouse.Backend.Services.Interfaces;
using Lighthouse.Backend.Services.Interfaces.DomainEvents;
using Lighthouse.Backend.Services.Interfaces.Repositories;
using Microsoft.Extensions.Logging;

namespace Lighthouse.Backend.Services.Implementation.DomainEvents
{
    /// <summary>
    /// Demo-only: after a demo owner refreshes, synthesizes a backdated percentile history so the
    /// Percentiles Over Time chart renders a populated trend on a freshly-loaded demo. The per-sync
    /// <see cref="PercentilesOverTimeRecordingHandler"/> is strictly forward-only (records "today"
    /// only), so a fresh demo has no past days to plot. This handler backfills the window once.
    ///
    /// Backdates BOTH over-time families, over one shared window so the widgets never disagree
    /// about their date range on a demo screenshot. Percentiles: cycle-time across the 30/60/90
    /// horizons, and work item age at the <see cref="PercentilesOverTimeSnapshot.NoHorizon"/>
    /// sentinel (age is always "as of today", so it has no horizon dimension). Process behaviour:
    /// the natural process limits of <see cref="ProcessBehaviorMetricType.Throughput"/>, which have
    /// no horizon dimension at all. Idempotency is evaluated PER FAMILY, so a demo owner that an
    /// earlier release backfilled with percentiles only still gains its throughput limits on the
    /// next refresh. Gated to demo connections (SynthesizeStateJourneyForDemo = true), so it never
    /// touches a real customer's data — real tenants stay forward-only (DDD-4).
    /// </summary>
    public class DemoPercentilesBackfillHandler
        : IDomainEventHandler<TeamDataRefreshed>,
          IDomainEventHandler<PortfolioFeaturesRefreshed>
    {
        private const int HistoryWindowDays = 14;

        private static readonly int[] CycleTimeHorizons = [30, 60, 90];

        private static readonly int[] WorkItemAgeHorizons = [PercentilesOverTimeSnapshot.NoHorizon];

        private readonly IRepository<Team> teamRepository;
        private readonly IRepository<Portfolio> portfolioRepository;
        private readonly IRepository<WorkTrackingSystemConnection> connectionRepository;
        private readonly IPercentilesOverTimeSnapshotRepository snapshotRepository;
        private readonly IProcessBehaviorSnapshotRepository processBehaviorSnapshotRepository;
        private readonly ILighthouseClock clock;
        private readonly ILogger<DemoPercentilesBackfillHandler> logger;

        public DemoPercentilesBackfillHandler(
            IRepository<Team> teamRepository,
            IRepository<Portfolio> portfolioRepository,
            IRepository<WorkTrackingSystemConnection> connectionRepository,
            IPercentilesOverTimeSnapshotRepository snapshotRepository,
            IProcessBehaviorSnapshotRepository processBehaviorSnapshotRepository,
            ILighthouseClock clock,
            ILogger<DemoPercentilesBackfillHandler> logger)
        {
            this.teamRepository = teamRepository;
            this.portfolioRepository = portfolioRepository;
            this.connectionRepository = connectionRepository;
            this.snapshotRepository = snapshotRepository;
            this.processBehaviorSnapshotRepository = processBehaviorSnapshotRepository;
            this.clock = clock;
            this.logger = logger;
        }

        public async Task HandleAsync(TeamDataRefreshed domainEvent, CancellationToken cancellationToken)
        {
            var team = teamRepository.GetById(domainEvent.TeamId);
            if (team == null || !IsDemoOwner(team))
            {
                return;
            }

            await BackfillAsync(team.Id, OwnerType.Team);
        }

        public async Task HandleAsync(PortfolioFeaturesRefreshed domainEvent, CancellationToken cancellationToken)
        {
            var portfolio = portfolioRepository.GetById(domainEvent.PortfolioId);
            if (portfolio == null || !IsDemoOwner(portfolio))
            {
                return;
            }

            await BackfillAsync(portfolio.Id, OwnerType.Portfolio);
        }

        private bool IsDemoOwner(WorkTrackingSystemOptionsOwner owner)
        {
            var connection = connectionRepository.GetById(owner.WorkTrackingSystemConnectionId);

            return connection != null
                && connection.Options.Any(option =>
                    option.Key == CsvWorkTrackingOptionNames.SynthesizeStateJourneyForDemo
                    && bool.TryParse(option.Value, out var synthesize) && synthesize);
        }

        private async Task BackfillAsync(int ownerId, OwnerType ownerType)
        {
            var todayDate = clock.Today;

            BackfillFamily(ownerId, ownerType, MetricType.CycleTime, CycleTimeHorizons, todayDate);
            BackfillFamily(ownerId, ownerType, MetricType.WorkItemAge, WorkItemAgeHorizons, todayDate);
            BackfillProcessBehaviorFamily(ownerId, ownerType, ProcessBehaviorMetricType.Throughput, todayDate);

            await snapshotRepository.Save();
            await processBehaviorSnapshotRepository.Save();
        }

        private void BackfillProcessBehaviorFamily(
            int ownerId, OwnerType ownerType, ProcessBehaviorMetricType metricType, DateOnly todayDate)
        {
            // Same per-family idempotency rule as the percentile families, evaluated against the
            // process-behaviour store: an owner an earlier release backfilled for percentiles only
            // must STILL gain its natural-process-limit history. An owner-scoped guard would make
            // every newly added family a permanent no-op wherever an older one already ran.
            var alreadyBackfilled = processBehaviorSnapshotRepository
                .GetAllByPredicate(snapshot =>
                    snapshot.OwnerId == ownerId
                    && snapshot.OwnerType == ownerType
                    && snapshot.MetricType == metricType
                    && snapshot.RecordedAt < todayDate)
                .Any();

            if (alreadyBackfilled)
            {
                return;
            }

            // Stryker disable once all: diagnostic log text is not behaviour
            logger.LogInformation(
                "Backfilling demo {MetricType} process behaviour history for {OwnerType} {OwnerId}",
                metricType, ownerType, ownerId);

            for (var daysAgo = HistoryWindowDays; daysAgo >= 1; daysAgo--)
            {
                var recordedAt = todayDate.AddDays(-daysAgo);
                var dayIndex = HistoryWindowDays - daysAgo;

                var limits = SynthesizeNaturalProcessLimits(dayIndex);
                UpsertProcessBehaviorSnapshot(ownerId, ownerType, metricType, recordedAt, limits);
            }
        }

        private static (int Lnpl, int Average, int Unpl) SynthesizeNaturalProcessLimits(int dayIndex)
        {
            // Same deterministic gentle wave as the percentile synthesis, so the two over-time
            // widgets on a demo screenshot move together. The limits are derived from the average by
            // a fixed spread, which makes LNPL < Average < UNPL structurally true for every day —
            // an inverted or degenerate (flat) triple would render a visibly broken chart.
            const int LimitSpread = 7;

            var average = 12 + (dayIndex % 5);
            return (average - LimitSpread, average, average + LimitSpread);
        }

        private void UpsertProcessBehaviorSnapshot(
            int ownerId, OwnerType ownerType, ProcessBehaviorMetricType metricType, DateOnly recordedAt,
            (int Lnpl, int Average, int Unpl) limits)
        {
            var existing = processBehaviorSnapshotRepository.GetByPredicate(snapshot =>
                snapshot.OwnerId == ownerId
                && snapshot.OwnerType == ownerType
                && snapshot.MetricType == metricType
                && snapshot.RecordedAt == recordedAt);

            if (existing != null)
            {
                existing.Lnpl = limits.Lnpl;
                existing.Average = limits.Average;
                existing.Unpl = limits.Unpl;
                return;
            }

            processBehaviorSnapshotRepository.Add(new ProcessBehaviorSnapshot
            {
                OwnerId = ownerId,
                OwnerType = ownerType,
                MetricType = metricType,
                RecordedAt = recordedAt,
                Lnpl = limits.Lnpl,
                Average = limits.Average,
                Unpl = limits.Unpl,
            });
        }

        private void BackfillFamily(
            int ownerId, OwnerType ownerType, MetricType metricType, int[] horizons, DateOnly todayDate)
        {
            // Idempotency is scoped to THIS metric family: a backdated snapshot of this family means
            // its history was already backfilled. Scoping matters — a shared "any family backdated"
            // check would make a newly-added family a permanent no-op wherever an older release
            // already backfilled a different one. The forward-only recording handler only writes
            // RecordedAt == today, so RecordedAt < today is a clean "backfill already ran" signal
            // that never collides with the live sync.
            var alreadyBackfilled = snapshotRepository
                .GetAllByPredicate(snapshot =>
                    snapshot.OwnerId == ownerId
                    && snapshot.OwnerType == ownerType
                    && snapshot.MetricType == metricType
                    && snapshot.RecordedAt < todayDate)
                .Any();

            if (alreadyBackfilled)
            {
                return;
            }

            // Stryker disable once all: diagnostic log text is not behaviour
            logger.LogInformation(
                "Backfilling demo {MetricType} percentile history for {OwnerType} {OwnerId}",
                metricType, ownerType, ownerId);

            for (var daysAgo = HistoryWindowDays; daysAgo >= 1; daysAgo--)
            {
                var recordedAt = todayDate.AddDays(-daysAgo);
                var dayIndex = HistoryWindowDays - daysAgo;

                foreach (var horizon in horizons)
                {
                    var percentiles = SynthesizePercentiles(dayIndex, horizon);
                    UpsertSnapshot(ownerId, ownerType, metricType, horizon, recordedAt, percentiles);
                }
            }
        }

        private static (int P50, int P70, int P85, int P95) SynthesizePercentiles(int dayIndex, int horizon)
        {
            // Deterministic gentle wave so the demo chart shows a trend, not a flat line. The horizon
            // offset keeps the three cycle-time lines visually distinct; work item age passes the
            // NoHorizon sentinel and so takes a zero offset. Percentiles are monotone non-decreasing.
            var p50 = 4 + (dayIndex % 5) + horizon / 30;
            var p70 = p50 + 3;
            var p85 = p70 + 4;
            var p95 = p85 + 5;
            return (p50, p70, p85, p95);
        }

        private void UpsertSnapshot(
            int ownerId, OwnerType ownerType, MetricType metricType, int horizon, DateOnly recordedAt,
            (int P50, int P70, int P85, int P95) percentiles)
        {
            var existing = snapshotRepository.GetByPredicate(snapshot =>
                snapshot.OwnerId == ownerId
                && snapshot.OwnerType == ownerType
                && snapshot.MetricType == metricType
                && snapshot.Horizon == horizon
                && snapshot.RecordedAt == recordedAt);

            if (existing != null)
            {
                existing.P50 = percentiles.P50;
                existing.P70 = percentiles.P70;
                existing.P85 = percentiles.P85;
                existing.P95 = percentiles.P95;
                return;
            }

            snapshotRepository.Add(new PercentilesOverTimeSnapshot
            {
                OwnerId = ownerId,
                OwnerType = ownerType,
                MetricType = metricType,
                Horizon = horizon,
                RecordedAt = recordedAt,
                P50 = percentiles.P50,
                P70 = percentiles.P70,
                P85 = percentiles.P85,
                P95 = percentiles.P95,
            });
        }
    }
}

using Lighthouse.Backend.Models;
using Lighthouse.Backend.Models.Events;
using Lighthouse.Backend.Services.Interfaces;
using Lighthouse.Backend.Services.Interfaces.DomainEvents;
using Lighthouse.Backend.Services.Interfaces.Repositories;
using Microsoft.Extensions.Logging;

namespace Lighthouse.Backend.Services.Implementation.DomainEvents
{
    public class PercentilesOverTimeRecordingHandler
        : IDomainEventHandler<TeamDataRefreshed>,
          IDomainEventHandler<PortfolioFeaturesRefreshed>
    {
        // Operator alerting groups failures by metric FAMILY, not by metric type: cycle time and work
        // item age are both percentile readings, so every failure this handler reports carries
        // "Percentiles". The ProcessBehavior family ships its own recorder.
        private const string MetricFamily = "Percentiles";

        private readonly ITeamMetricsService teamMetricsService;
        private readonly IPortfolioMetricsService portfolioMetricsService;
        private readonly IRepository<Team> teamRepository;
        private readonly IRepository<Portfolio> portfolioRepository;
        private readonly IPercentilesOverTimeSnapshotRepository snapshotRepository;
        private readonly IPercentileSnapshotWriter snapshotWriter;
        private readonly ILogger<PercentilesOverTimeRecordingHandler> logger;

        public PercentilesOverTimeRecordingHandler(
            ITeamMetricsService teamMetricsService,
            IPortfolioMetricsService portfolioMetricsService,
            IRepository<Team> teamRepository,
            IRepository<Portfolio> portfolioRepository,
            IPercentilesOverTimeSnapshotRepository snapshotRepository,
            IPercentileSnapshotWriter snapshotWriter,
            ILogger<PercentilesOverTimeRecordingHandler> logger)
        {
            this.teamMetricsService = teamMetricsService;
            this.portfolioMetricsService = portfolioMetricsService;
            this.teamRepository = teamRepository;
            this.portfolioRepository = portfolioRepository;
            this.snapshotRepository = snapshotRepository;
            this.snapshotWriter = snapshotWriter;
            this.logger = logger;
        }

        public async Task HandleAsync(TeamDataRefreshed domainEvent, CancellationToken cancellationToken)
        {
            var team = teamRepository.GetById(domainEvent.TeamId);
            if (team == null)
            {
                return;
            }

            await RecordAsync(
                domainEvent.TeamId,
                OwnerType.Team,
                PercentileFamilies.For(team, teamMetricsService),
                () => teamMetricsService.InvalidateTeamMetrics(team));
        }

        public async Task HandleAsync(PortfolioFeaturesRefreshed domainEvent, CancellationToken cancellationToken)
        {
            var portfolio = portfolioRepository.GetById(domainEvent.PortfolioId);
            if (portfolio == null)
            {
                return;
            }

            await RecordAsync(
                domainEvent.PortfolioId,
                OwnerType.Portfolio,
                PercentileFamilies.For(portfolio, portfolioMetricsService),
                () => portfolioMetricsService.InvalidatePortfolioMetrics(portfolio));
        }

        private async Task RecordAsync(
            int ownerId,
            OwnerType ownerType,
            IReadOnlyList<PercentileFamilyReader> families,
            Action invalidateReadCache)
        {
            try
            {
                // Every family shares this one pass — a recorder per family would multiply the refresh
                // cost and drift from the cycle-time rows the others are meant to sit beside.
                foreach (var family in families)
                {
                    RecordFamily(ownerId, ownerType, family);
                }

                await snapshotRepository.Save();
            }
            catch (Exception exception)
            {
                LogRecordingFailure(exception, ownerType, ownerId);
            }
            finally
            {
                // Reading the point-in-time percentiles above warms the shared metrics cache under the
                // same (owner, window) keys the Flow Overview widgets read. Recording runs on the refresh
                // event, which can fire on partially-seeded data (e.g. demo load), so leaving those entries
                // behind would serve the UI a stale snapshot instead of a value computed on the settled data.
                // Invalidate what we warmed so the UI recomputes lazily — restoring the post-refresh
                // "cache empty, compute on first read" behaviour that predates this handler.
                invalidateReadCache();
            }
        }

        private void RecordFamily(int ownerId, OwnerType ownerType, PercentileFamilyReader family)
        {
            try
            {
                snapshotWriter.RecordToday(ownerId, ownerType, family.MetricType, family.ReadPercentiles);
            }
            catch (Exception exception)
            {
                // Contained per family so a failing family never discards the rows the other one
                // already staged — the caller's single Save() still persists them.
                LogRecordingFailure(exception, ownerType, ownerId);
            }
        }

        private void LogRecordingFailure(Exception exception, OwnerType ownerType, int ownerId)
        {
            logger.LogError(
                exception,
                "Percentile snapshot recording failed for {OwnerType} {OwnerId} ({MetricFamily})",
                ownerType,
                ownerId,
                MetricFamily);
        }
    }
}

