using Lighthouse.Backend.Models.Metrics;

namespace Lighthouse.Backend.Services.Implementation
{
    public record XmRResult(
        int Average,
        int UpperNaturalProcessLimit,
        int LowerNaturalProcessLimit,
        IReadOnlyList<IReadOnlyList<SpecialCauseType>> SpecialCauseClassifications);

    public static class XmRCalculator
    {
        private const double MovingRangeMultiplier = 2.66;

        public static XmRResult Calculate(int[] baselineValues, int[] displayValues)
        {
            if (baselineValues.Length == 0)
            {
                var emptyClassifications = CreateEmptyClassifications(displayValues.Length);
                return new XmRResult(0, 0, 0, emptyClassifications);
            }

            var average = baselineValues.Average();

            if (baselineValues.Length < 2)
            {
                var classifications = CreateEmptyClassifications(displayValues.Length);
                var roundedAverage = (int)Math.Round(average);
                return new XmRResult(roundedAverage, roundedAverage, roundedAverage, classifications);
            }

            var movingRanges = new double[baselineValues.Length - 1];
            for (var i = 1; i < baselineValues.Length; i++)
            {
                movingRanges[i - 1] = Math.Abs(baselineValues[i] - baselineValues[i - 1]);
            }

            var mrBar = movingRanges.Average();

            var unpl = average + MovingRangeMultiplier * mrBar;
            var lnpl = average - MovingRangeMultiplier * mrBar;

            // Zero-bounded data: clamp negative lower sigma lines to zero.
            // When a sigma line is zero it is considered not drawn and
            // any detection rule that depends on it becomes invalid.
            lnpl = lnpl < 0 ? 0 : lnpl;

            var sigma = mrBar / 1.128;

            var specialCauseClassifications = ClassifyAllPoints(
                displayValues, average, unpl, lnpl, sigma);

            return new XmRResult((int)Math.Round(average), (int)Math.Round(unpl), (int)Math.Round(lnpl), specialCauseClassifications);
        }

        private static SpecialCauseType[][] CreateEmptyClassifications(int length)
        {
            var classifications = new SpecialCauseType[length][];
            for (var i = 0; i < length; i++)
            {
                classifications[i] = [];
            }

            return classifications;
        }

        private static List<List<SpecialCauseType>> ClassifyAllPoints(
            int[] values,
            double average,
            double unpl,
            double lnpl,
            double sigma)
        {
            var oneSigmaUpper = average + sigma;
            var twoSigmaUpper = average + 2 * sigma;
            var oneSigmaLower = Math.Max(0, average - sigma);
            var twoSigmaLower = Math.Max(0, average - 2 * sigma);

            var causeSets = InitializeCauseSets(values.Length);

            ApplyLargeChangeRule(values, unpl, lnpl, causeSets);
            ApplyModerateChangeRule(values, twoSigmaUpper, twoSigmaLower, average, causeSets);
            ApplyModerateShiftRule(values, oneSigmaUpper, oneSigmaLower, average, causeSets);
            ApplySmallShiftRule(values, average, causeSets);

            return ConvertCauseSetsToResult(causeSets);
        }

        private static HashSet<SpecialCauseType>[] InitializeCauseSets(int length)
        {
            var causeSets = new HashSet<SpecialCauseType>[length];
            for (var i = 0; i < length; i++)
            {
                causeSets[i] = [];
            }
            return causeSets;
        }

        private static void ApplyLargeChangeRule(
            int[] values,
            double unpl,
            double lnpl,
            HashSet<SpecialCauseType>[] causeSets)
        {
            var isLnplValid = lnpl > 0;

            for (var i = 0; i < values.Length; i++)
            {
                if (values[i] > unpl || (isLnplValid && values[i] < lnpl))
                {
                    causeSets[i].Add(SpecialCauseType.LargeChange);
                }
            }
        }

        private static void ApplyModerateChangeRule(
            int[] values,
            double twoSigmaUpper,
            double twoSigmaLower,
            double average,
            HashSet<SpecialCauseType>[] causeSets)
        {
            var isTwoSigmaLowerValid = twoSigmaLower > 0;

            for (var i = 2; i < values.Length; i++)
            {
                CheckModerateChangeAbove(values, twoSigmaUpper, average, causeSets, i);

                if (isTwoSigmaLowerValid)
                {
                    CheckModerateChangeBelow(values, twoSigmaLower, average, causeSets, i);
                }
            }
        }

        private static void CheckModerateChangeAbove(
            int[] values,
            double twoSigmaUpper,
            double average,
            HashSet<SpecialCauseType>[] causeSets,
            int endIndex)
        {
            // Count points that are beyond 2-sigma upper
            var countBeyondThreshold = 0;
            for (var j = endIndex - 2; j <= endIndex; j++)
            {
                if (values[j] > twoSigmaUpper)
                {
                    countBeyondThreshold++;
                }
            }

            // Rule requires 2 of 3 beyond threshold
            if (countBeyondThreshold >= 2)
            {
                // Mark only points that are above average (same side as the signal)
                for (var j = endIndex - 2; j <= endIndex; j++)
                {
                    if (values[j] > average)
                    {
                        causeSets[j].Add(SpecialCauseType.ModerateChange);
                    }
                }
            }
        }

        private static void CheckModerateChangeBelow(
            int[] values,
            double twoSigmaLower,
            double average,
            HashSet<SpecialCauseType>[] causeSets,
            int endIndex)
        {
            // Count points that are beyond 2-sigma lower
            var countBeyondThreshold = 0;
            for (var j = endIndex - 2; j <= endIndex; j++)
            {
                if (values[j] < twoSigmaLower)
                {
                    countBeyondThreshold++;
                }
            }

            // Rule requires 2 of 3 beyond threshold
            if (countBeyondThreshold >= 2)
            {
                // Mark only points that are below average (same side as the signal)
                for (var j = endIndex - 2; j <= endIndex; j++)
                {
                    if (values[j] < average)
                    {
                        causeSets[j].Add(SpecialCauseType.ModerateChange);
                    }
                }
            }
        }

        private static void ApplyModerateShiftRule(
            int[] values,
            double oneSigmaUpper,
            double oneSigmaLower,
            double average,
            HashSet<SpecialCauseType>[] causeSets)
        {
            var isOneSigmaLowerValid = oneSigmaLower > 0;

            for (var i = 4; i < values.Length; i++)
            {
                CheckModerateShiftAbove(values, oneSigmaUpper, average, causeSets, i);

                if (isOneSigmaLowerValid)
                {
                    CheckModerateShiftBelow(values, oneSigmaLower, average, causeSets, i);
                }
            }
        }

        private static void CheckModerateShiftAbove(
            int[] values,
            double oneSigmaUpper,
            double average,
            HashSet<SpecialCauseType>[] causeSets,
            int endIndex)
        {
            // Count points that are beyond 1-sigma upper
            var countBeyondThreshold = 0;
            for (var j = endIndex - 4; j <= endIndex; j++)
            {
                if (values[j] > oneSigmaUpper)
                {
                    countBeyondThreshold++;
                }
            }

            // Rule requires 4 of 5 beyond threshold
            if (countBeyondThreshold >= 4)
            {
                // Mark only points that are above average (same side as the signal)
                for (var j = endIndex - 4; j <= endIndex; j++)
                {
                    if (values[j] > average)
                    {
                        causeSets[j].Add(SpecialCauseType.ModerateShift);
                    }
                }
            }
        }

        private static void CheckModerateShiftBelow(
            int[] values,
            double oneSigmaLower,
            double average,
            HashSet<SpecialCauseType>[] causeSets,
            int endIndex)
        {
            // Count points that are beyond 1-sigma lower
            var countBeyondThreshold = 0;
            for (var j = endIndex - 4; j <= endIndex; j++)
            {
                if (values[j] < oneSigmaLower)
                {
                    countBeyondThreshold++;
                }
            }

            // Rule requires 4 of 5 beyond threshold
            if (countBeyondThreshold >= 4)
            {
                // Mark only points that are below average (same side as the signal)
                for (var j = endIndex - 4; j <= endIndex; j++)
                {
                    if (values[j] < average)
                    {
                        causeSets[j].Add(SpecialCauseType.ModerateShift);
                    }
                }
            }
        }

        private static void ApplySmallShiftRule(
            int[] values,
            double average,
            HashSet<SpecialCauseType>[] causeSets)
        {
            for (var i = 7; i < values.Length; i++)
            {
                if (AreAllPointsOnSameSideOfAverage(values, i - 7, i, average))
                {
                    MarkPointsInWindow(causeSets, i - 7, i, SpecialCauseType.SmallShift);
                }
            }
        }

        private static bool AreAllPointsOnSameSideOfAverage(
            int[] values,
            int startIndex,
            int endIndex,
            double average)
        {
            var allAbove = true;
            var allBelow = true;

            for (var j = startIndex; j <= endIndex; j++)
            {
                if (values[j] < average)
                {
                    allAbove = false;
                }
                else if (values[j] > average)
                {
                    allBelow = false;
                }
                else  // values[j] == average
                {
                    // Point exactly on average breaks both runs
                    return false;
                }
            }

            return allAbove || allBelow;
        }

        private static void MarkPointsInWindow(
            HashSet<SpecialCauseType>[] causeSets,
            int startIndex,
            int endIndex,
            SpecialCauseType causeType)
        {
            for (var j = startIndex; j <= endIndex; j++)
            {
                causeSets[j].Add(causeType);
            }
        }

        private static List<List<SpecialCauseType>> ConvertCauseSetsToResult(
            HashSet<SpecialCauseType>[] causeSets)
        {
            var result = new List<List<SpecialCauseType>>(causeSets.Length);
            foreach (var cause in causeSets)
            {
                var list = cause.Count > 0
                    ? cause.OrderBy(c => c).ToList()
                    : [];
                result.Add(list);
            }

            return result;
        }
    }
}

using Lighthouse.Backend.Models;

namespace Lighthouse.Backend.Services.Interfaces.BackgroundServices
{
    /// <summary>
    /// One owner's run of days that carry no over-time reading yet, handed over to be worked out
    /// somewhere other than the request that noticed them. The days are candidates rather than
    /// instructions: the pass still drops any that fall past the owner's last observation, which it
    /// can only know once it has loaded the owner.
    ///
    /// The ask names no metric because a pass covers every chart the owner has - percentiles and
    /// process limits alike. Naming one would let the two fill at different moments, which is the
    /// defect this whole seam exists to prevent: a lead comparing the limits chart against the
    /// percentile tabs would be comparing two different stretches of history.
    /// </summary>
    public sealed record OverTimeFillRequest(
        int OwnerId,
        OwnerType OwnerType,
        IReadOnlyList<DateOnly> CandidateDays)
    {
        /// <summary>
        /// What makes two asks the same ask. Opening the same chart three times while the first walk
        /// is still running must not queue the same walk three times.
        ///
        /// The owner and nothing finer, which is only safe because a pass covers all of that owner's
        /// charts. Collapse the key without widening the pass and an ask gets dropped while work it
        /// covers is still outstanding - the family it named would then never be filled at all.
        /// </summary>
        public (int OwnerId, OwnerType OwnerType) Key => (OwnerId, OwnerType);
    }

    /// <summary>
    /// Whether history is being filled in at this instant, and nothing else. The database maintenance
    /// gate needs that one fact before it lets an operator swap the database file out from under an
    /// open write, and must not be able to reach past it into starting, stopping or queueing a fill.
    /// </summary>
    public interface IOverTimeHistoryFillActivity
    {
        bool HasPassInFlight { get; }
    }

    public interface IOverTimeHistoryFiller : IOverTimeHistoryFillActivity
    {
        /// <summary>
        /// Takes the ask and returns immediately. Never throws and never blocks: the caller is a read
        /// a person is waiting on, and nothing about filling in history is worth making them wait for.
        /// </summary>
        void AskFor(OverTimeFillRequest request);

        /// <summary>
        /// Runs every ask waiting right now, one pass at a time on the caller, and returns once the
        /// queue is empty or cancellation is requested; whatever is still waiting then stays queued.
        /// It does not wait for a pass the background loop has already taken off the queue - that one
        /// finishes on the loop. Separate from the background loop so that whoever needs the queue
        /// emptied at a moment they choose - a test above all, since the test host runs no background
        /// work and so every pass there runs here - can have exactly that instead of sleeping.
        /// </summary>
        Task DrainAsync(CancellationToken cancellationToken);
    }
}

using Lighthouse.Backend.Models;

namespace Lighthouse.Backend.Services.Interfaces
{
    /// <summary>
    /// Notices which days of a requested window carry no reading yet and asks for them. It runs on the
    /// thread a person is waiting on, so it may only look at rows that read has already materialised -
    /// no further query, and nothing that writes.
    ///
    /// The days already held arrive as bare dates rather than as rows, because either over-time chart
    /// may be the one that noticed the gap and neither kind of row says anything here beyond which day
    /// it covers. What then gets filled follows from the owner rather than from whichever chart
    /// happened to be open.
    ///
    /// Returns nothing on purpose: a reader gets the series that exists at the moment they asked, and
    /// what is missing arrives on a later visit. A return value here would be something a caller could
    /// be tempted to wait for.
    /// </summary>
    public interface IOverTimeGapReconciler
    {
        void AskForTheDaysThatAreMissing(
            int ownerId,
            OwnerType ownerType,
            DateOnly? from,
            DateOnly? to,
            IReadOnlyList<DateOnly> daysAlreadyHeld);
    }
}

using Lighthouse.Backend.Models;
using Lighthouse.Backend.Models.Metrics;

namespace Lighthouse.Backend.Services.Interfaces
{
    /// <summary>
    /// One percentile family of one owner, together with the chart to read it from. The reader is
    /// called with the window start and the window end, and returns that window's readings.
    /// </summary>
    public sealed record PercentileFamilyReader(
        MetricType MetricType,
        Func<DateTime, DateTime, IEnumerable<PercentileValue>> ReadPercentiles);

    /// <summary>
    /// Computes one calendar day of percentile snapshot rows for one owner and one metric family and
    /// stages them on the snapshot store. Every path that produces a percentile day goes through here,
    /// so a day rebuilt from history and a day recorded live cannot be computed differently.
    ///
    /// Recording today stages only: the caller calls Save, so several families staged by one caller
    /// persist together and one failing family never discards what another already staged. Filling a
    /// gap persists through SaveFilledDay instead, because a day that collides with another copy of
    /// the application has to be dropped on its own rather than take the rest of the walk with it.
    ///
    /// The window reader is handed in because the owner kind decides which metrics service answers it.
    /// It is called with the window start and the window end, and returns that window's readings.
    /// </summary>
    public interface IPercentileSnapshotWriter
    {
        /// <summary>
        /// Computes today and overwrites whatever is already stored for it. Today's value legitimately
        /// changes as the day goes on, so the last computation of the day is the right one to keep.
        /// </summary>
        void RecordToday(
            int ownerId,
            OwnerType ownerType,
            MetricType metricType,
            Func<DateTime, DateTime, IEnumerable<PercentileValue>> readPercentiles);

        /// <summary>
        /// Computes <paramref name="day"/> only where nothing is stored for it yet, and leaves any day
        /// that already carries a value untouched.
        /// </summary>
        void FillDayIfAbsent(
            int ownerId,
            OwnerType ownerType,
            MetricType metricType,
            DateOnly day,
            Func<DateTime, DateTime, IEnumerable<PercentileValue>> readPercentiles);

        /// <summary>
        /// Persists what the last <see cref="FillDayIfAbsent"/> staged, one day at a time.
        ///
        /// Two copies of the application can both find a day absent and both go on to write it. The
        /// database refuses the second on the natural key, and absorbing that refusal here is what
        /// makes the duplicate work cost nothing: the refused row is dropped and the caller carries on
        /// with the next day. Saving per day rather than per pass is the whole point - a collision on
        /// one day must not abandon the eighty-nine after it.
        /// </summary>
        Task SaveFilledDay();
    }
}

